const { G } = require("../_guide.js");
const P = (t, m, k, a) => ({ t, m, k, a });
const Q = (c, q, parts) => ({ c, q, g: G(parts.map(p => p.m)), parts });
module.exports = {
  open: [
    /* ---------- Sherry ---------- */
    Q("d5a", ["Le uve dello Sherry nascono in un clima caldo, ma su un suolo particolare.", "Les raisins du Xérès naissent dans un climat chaud, mais sur un sol particulier.", "Sherry grapes grow in a hot climate, but on a special soil.", "Las uvas del Jerez nacen en un clima cálido, pero sobre un suelo especial."], [
      P(["Spiega come clima, suoli e gestione del vigneto della zona di Jerez influenzano le uve destinate allo Sherry.", "Expliquez comment le climat, les sols et la conduite du vignoble de la zone de Jerez influencent les raisins destinés au Xérès.", "Explain how the climate, soils and vineyard management of the Jerez area influence the grapes grown for Sherry.", "Explica cómo el clima, los suelos y la gestión del viñedo de la zona de Jerez influyen en las uvas destinadas al Jerez."], 10,
        ["mediterraneo caldo, 36° N, molti giorni senza nuvole: maturazione piena; poniente umido dall'Atlantico, levante caldo e secco che concentra lo zucchero; troppo zucchero rende difficile fermentare a secco, un problema per il flor; albariza: calcare, silice e argilla; l'albariza trattiene la pioggia invernale e la rilascia, la crosta riduce l'evaporazione; densità 3.500–4.000 ceppi/ha e rese medie di 70 hL/ha; il suolo bianco riflette la luce: rischio di scottature, serve ombra; Palomino 97%, neutro, resistente alla siccità, produttivo; Palomino perde acidità in fretta: acidificazione; aserpia: solchi che trattengono l'acqua piovana; vendemmia da inizio agosto, circa 12% potenziale, spesso a macchina di notte",
         "méditerranéen chaud, 36° N, nombreux jours sans nuages : pleine maturité ; poniente humide venu de l'Atlantique, levante chaud et sec qui concentre le sucre ; trop de sucre rend difficile une fermentation à sec, un problème pour la flor ; albariza : calcaire, silice et argile ; l'albariza stocke la pluie d'hiver et la restitue, la croûte limite l'évaporation ; densité de 3 500 à 4 000 pieds/ha et rendements moyens de 70 hL/ha ; le sol blanc réfléchit la lumière : risque de brûlures, il faut de l'ombre ; Palomino 97 %, neutre, résistant à la sécheresse, productif ; le Palomino perd vite son acidité : acidification ; aserpia : sillons qui retiennent l'eau de pluie ; vendange dès début août, environ 12 % potentiel, souvent à la machine de nuit",
         "hot Mediterranean, 36° N, many cloudless days: full ripeness; damp poniente from the Atlantic, hot dry levante that concentrates sugar; too much sugar makes fermenting to dryness hard, a problem for flor; albariza: limestone, silica and clay; albariza stores winter rain and releases it, its crust reduces evaporation; density of 3,500–4,000 vines/ha and average yields of 70 hL/ha; the white soil reflects light: sunburn risk, shade needed; Palomino 97%, neutral, drought-resistant, productive; Palomino loses acidity quickly: acidification; aserpia: troughs that hold rainwater; harvest from early August, about 12% potential, often by machine at night",
         "mediterráneo cálido, 36° N, muchos días despejados: madurez plena; poniente húmedo del Atlántico, levante cálido y seco que concentra el azúcar; demasiado azúcar dificulta fermentar en seco, un problema para la flor; albariza: caliza, sílice y arcilla; la albariza almacena la lluvia invernal y la libera, su costra reduce la evaporación; densidad de 3.500–4.000 cepas/ha y rendimientos medios de 70 hL/ha; el suelo blanco refleja la luz: riesgo de quemaduras, hace falta sombra; Palomino 97 %, neutra, resistente a la sequía, productiva; la Palomino pierde acidez deprisa: acidificación; aserpia: surcos que retienen el agua de lluvia; vendimia desde principios de agosto, unos 12 % potenciales, a menudo a máquina de noche"],
        ["Jerez, a 36° N e quasi al livello del mare, ha un clima mediterraneo caldo con estati secche e molti giorni senza nuvole: le uve maturano pienamente senza difficoltà. Due venti contano. Il poniente, umido e fresco, arriva dall'Atlantico; il levante, caldo e secco, accelera la traspirazione degli acini e concentra lo zucchero, ma un mosto troppo ricco fatica a fermentare a secco, ed è un problema per i vini destinati al flor. La chiave è l'albariza, un suolo di calcare, silice e argilla nato da antichi organismi marini: poroso come una spugna, immagazzina la pioggia invernale e la cede durante l'estate asciutta, mentre la crosta che forma seccandosi riduce l'evaporazione. Per questo si piantano 3.500–4.000 ceppi per ettaro e si ottengono in media 70 hL/ha, molto più che in altre zone calde della Spagna. Il colore chiaro riflette la luce sulla chioma ma espone i grappoli alle scottature, quindi serve fogliame che li ombreggi. Il Palomino, 97% del vigneto, è neutro, produttivo e resistente alla siccità: la neutralità è un pregio, perché gli aromi verranno dalla maturazione, e rese alte non nuocciono. Perde però acidità in fretta, quindi si vendemmia presto, da inizio agosto, a circa 12% di potenziale, e spesso si acidifica. Dopo la vendemmia si scavano solchi lungo le curve di livello (aserpia) per trattenere la pioggia; la vendemmia, per il 60% a macchina, si fa di notte per limitare ossidazione e alterazioni.",
         "Jerez, à 36° N et presque au niveau de la mer, a un climat méditerranéen chaud aux étés secs et aux nombreux jours sans nuages : les raisins mûrissent pleinement sans difficulté. Deux vents comptent. Le poniente, frais et humide, vient de l'Atlantique ; le levante, chaud et sec, accélère la transpiration des baies et concentre le sucre, mais un moût trop riche fermente difficilement à sec, ce qui gêne les vins destinés à la flor. La clé est l'albariza, un sol de calcaire, silice et argile issu d'anciens organismes marins : poreuse comme une éponge, elle stocke la pluie d'hiver et la restitue pendant l'été sec, tandis que la croûte qui se forme en séchant limite l'évaporation. On plante donc 3 500 à 4 000 pieds par hectare et l'on obtient en moyenne 70 hL/ha, bien plus que dans d'autres zones chaudes d'Espagne. Sa couleur claire renvoie la lumière vers le feuillage mais expose les grappes aux brûlures, d'où la nécessité d'un feuillage qui les ombrage. Le Palomino, 97 % du vignoble, est neutre, productif et résistant à la sécheresse : sa neutralité est un atout, car les arômes viendront de l'élevage, et des rendements élevés ne nuisent pas. Il perd cependant vite son acidité : on vendange tôt, dès début août, vers 12 % de potentiel, et l'on acidifie souvent. Après la vendange on creuse des sillons suivant les courbes de niveau (aserpia) pour retenir la pluie ; la récolte, à 60 % mécanique, se fait de nuit pour limiter oxydation et altérations.",
         "Jerez, at 36° N and almost at sea level, has a hot Mediterranean climate with dry summers and many cloudless days: grapes ripen fully without difficulty. Two winds matter. The cool, damp poniente comes from the Atlantic; the hot, dry levante speeds up transpiration from the berries and concentrates sugar, but an overly rich must struggles to ferment dry, which is a problem for wines destined for flor. The key is albariza, a soil of limestone, silica and clay formed from ancient marine organisms: porous like a sponge, it stores winter rain and releases it through the dry summer, while the crust it forms as it dries reduces evaporation. This is why vines are planted at 3,500–4,000 per hectare and average 70 hL/ha, far more than in other hot parts of Spain. Its pale colour reflects light onto the canopy but exposes bunches to sunburn, so foliage is needed to shade them. Palomino, 97% of the vineyard, is neutral, productive and drought-resistant: neutrality is an asset, because the aromas will come from maturation, and high yields do no harm. It loses acidity quickly, however, so harvest is early, from the start of August, at about 12% potential, and acidification is common. After harvest, troughs are dug along the contours (aserpia) to hold rainwater; the harvest, 60% by machine, takes place at night to limit oxidation and spoilage.",
         "Jerez, a 36° N y casi al nivel del mar, tiene un clima mediterráneo cálido con veranos secos y muchos días despejados: la uva madura plenamente sin dificultad. Cuentan dos vientos. El poniente, fresco y húmedo, llega del Atlántico; el levante, cálido y seco, acelera la transpiración de las bayas y concentra el azúcar, pero un mosto demasiado rico fermenta con dificultad en seco, lo que perjudica a los vinos destinados a la flor. La clave es la albariza, un suelo de caliza, sílice y arcilla formado por antiguos organismos marinos: porosa como una esponja, almacena la lluvia invernal y la cede durante el verano seco, mientras la costra que forma al secarse reduce la evaporación. Por eso se plantan 3.500–4.000 cepas por hectárea y se obtienen de media 70 hL/ha, mucho más que en otras zonas cálidas de España. Su color claro refleja la luz hacia la vegetación pero expone los racimos a quemaduras, así que hace falta follaje que los sombree. La Palomino, el 97 % del viñedo, es neutra, productiva y resistente a la sequía: la neutralidad es una virtud, porque los aromas vendrán de la crianza, y los rendimientos altos no perjudican. Pierde acidez deprisa, así que se vendimia pronto, desde principios de agosto, con unos 12 % potenciales, y a menudo se acidifica. Tras la vendimia se abren surcos siguiendo las curvas de nivel (aserpia) para retener la lluvia; la vendimia, en un 60 % a máquina, se hace de noche para limitar oxidación y alteraciones."])]),
    Q("d5a", ["Dalla stessa uva e dallo stesso vigneto nascono Fino, Amontillado, Palo Cortado e Oloroso.", "Du même raisin et du même vignoble naissent Fino, Amontillado, Palo Cortado et Oloroso.", "The same grape and the same vineyard give Fino, Amontillado, Palo Cortado and Oloroso.", "De la misma uva y el mismo viñedo nacen Fino, Amontillado, Palo Cortado y Oloroso."], [
      P(["Spiega come la pressatura e le due classificazioni decidono il percorso di ogni vino e come questo si riflette su stile, qualità e prezzo di Amontillado e Palo Cortado.", "Expliquez comment le pressurage et les deux classifications décident du parcours de chaque vin, et comment cela se traduit dans le style, la qualité et le prix de l'Amontillado et du Palo Cortado.", "Explain how pressing and the two classifications decide the path of each wine, and how this shows in the style, quality and price of Amontillado and Palo Cortado.", "Explica cómo el prensado y las dos clasificaciones deciden el camino de cada vino, y cómo se refleja en el estilo, la calidad y el precio del Amontillado y el Palo Cortado."], 12,
        ["mosto fiore e primera yema, pochi fenoli, per l'invecchiamento biologico; segunda yema, più fenoli che frenano il flor, per l'Oloroso; prima classificazione dopo la fermentazione: vini leggeri a 15–15,5%, vini più pieni a 17%; seconda classificazione dopo alcuni mesi: flor pieno e vino fresco = Fino o Manzanilla; vino meno delicato = Palo Cortado; Amontillado: prima in una solera di Fino, poi flor esaurito o rifortificato a 17%, solera ossidativa; Amontillado: mela, mandorla, pane più spezie, erbe e tabacco, secco, corpo più leggero; Palo Cortado: base da Fino, flor insufficiente, rifortificato a 17%, maturazione ossidativa; Palo Cortado: naso da Amontillado, palato da Oloroso, 17–22%, meno di 5 g/L; Palo Cortado più rotondo perché resta più glicerolo; Amontillado economico da criaderas giovani, i migliori fino al super-premium; Palo Cortado di solito premium, molto buono o eccezionale",
         "jus de goutte et primera yema, peu de phénols, pour l'élevage biologique ; segunda yema, plus de phénols qui freinent la flor, pour l'Oloroso ; première classification après la fermentation : vins légers à 15–15,5 %, vins plus amples à 17 % ; seconde classification après quelques mois : flor complète et vin frais = Fino ou Manzanilla ; vin moins délicat = Palo Cortado ; Amontillado : d'abord dans une solera de Fino, puis flor épuisée ou remutage à 17 %, solera oxydative ; Amontillado : pomme, amande, pain puis épices, herbes et tabac, sec, corps plus léger ; Palo Cortado : base de qualité Fino, flor insuffisante, remuté à 17 %, élevage oxydatif ; Palo Cortado : nez d'Amontillado, bouche d'Oloroso, 17–22 %, moins de 5 g/L ; Palo Cortado plus rond car il garde plus de glycérol ; Amontillado bon marché issu de criaderas jeunes, les meilleurs jusqu'au super-premium ; Palo Cortado le plus souvent premium, très bon à exceptionnel",
         "free run and primera yema, few phenolics, for biological ageing; segunda yema, more phenolics that hinder flor, for Oloroso; first classification after fermentation: light wines to 15–15.5%, fuller wines to 17%; second classification after some months: full flor and fresh wine = Fino or Manzanilla; less delicate wine = Palo Cortado; Amontillado: first in a Fino solera, then flor dies or refortified to 17%, oxidative solera; Amontillado: apple, almond, bread then spice, herbs and tobacco, dry, lighter body; Palo Cortado: Fino-quality base, not enough flor, refortified to 17%, oxidative ageing; Palo Cortado: Amontillado nose, Oloroso palate, 17–22%, under 5 g/L; Palo Cortado rounder because more glycerol remains; inexpensive Amontillado from young criaderas, the best up to super-premium; Palo Cortado mostly premium, very good to outstanding",
         "mosto yema y primera yema, pocos fenoles, para la crianza biológica; segunda yema, más fenoles que frenan la flor, para el Oloroso; primera clasificación tras la fermentación: vinos ligeros a 15–15,5 %, vinos más llenos a 17 %; segunda clasificación tras unos meses: flor completa y vino fresco = Fino o Manzanilla; vino menos delicado = Palo Cortado; Amontillado: primero en una solera de Fino, luego flor agotada o reencabezado a 17 %, solera oxidativa; Amontillado: manzana, almendra, pan y luego especias, hierbas y tabaco, seco, cuerpo más ligero; Palo Cortado: base de calidad de Fino, flor insuficiente, reencabezado a 17 %, crianza oxidativa; Palo Cortado: nariz de Amontillado, boca de Oloroso, 17–22 %, menos de 5 g/L; Palo Cortado más redondo porque conserva más glicerol; Amontillado económico de criaderas jóvenes, los mejores hasta super-premium; Palo Cortado casi siempre premium, muy bueno a excepcional"],
        ["Il percorso comincia alla pressa. Il mosto fiore e la primera yema, poveri di fenoli, servono ai vini biologici, perché i fenoli frenano lo sviluppo del flor; la segunda yema, ottenuta con più pressione, va di solito all'Oloroso. Dopo la fermentazione ogni partita è assaggiata e analizzata (prima classificazione): i vini più leggeri e delicati sono fortificati a 15–15,5%, l'alcol ideale per il flor; quelli più pieni a 17%, livello al quale il flor non sopravvive, ed entrano direttamente in una solera di Oloroso. Dopo alcuni mesi i vini biologici sono riesaminati (seconda classificazione): quelli con un velo di flor pieno e rimasti freschi diventano Fino o Manzanilla; quelli un po' meno delicati sono destinati al Palo Cortado. L'Amontillado passa prima per una solera di Fino; poi il flor si esaurisce oppure il vino è rifortificato a 17%, e continua ossidativamente in una solera di Amontillado. Unisce quindi mela, mandorla e pane del flor a spezie, erbe e tabacco; è secco, sopra il 16%, con un corpo leggero perché il flor ha consumato il glicerolo. Il Palo Cortado nasce da una base di qualità da Fino che non ha sviluppato abbastanza flor: rifortificato a 17%, matura ossidativamente. Ha il naso di un Amontillado ma un palato più vicino all'Oloroso, 17–22% e meno di 5 g/L di zucchero; avendo passato meno tempo sotto flor, conserva più glicerolo ed è più rotondo. Le due fasi non hanno durate fissate, quindi gli Amontillado variano molto: quelli economici usano vini giovani delle prime criaderas, i più vecchi e complessi vanno dal prezzo medio al super-premium. Il Palo Cortado, raro, è di solito molto buono o eccezionale e premium.",
         "Le parcours commence au pressoir. Le jus de goutte et la primera yema, pauvres en phénols, servent aux vins biologiques, car les phénols freinent la flor ; la segunda yema, obtenue avec plus de pression, va en général à l'Oloroso. Après la fermentation, chaque lot est dégusté et analysé (première classification) : les vins les plus légers et délicats sont mutés à 15–15,5 %, l'alcool idéal pour la flor ; les plus amples à 17 %, niveau auquel la flor ne survit pas, et entrent directement dans une solera d'Oloroso. Quelques mois plus tard, les vins biologiques sont réexaminés (seconde classification) : ceux qui portent une flor complète et sont restés frais deviennent Fino ou Manzanilla ; ceux un peu moins délicats sont destinés au Palo Cortado. L'Amontillado passe d'abord par une solera de Fino ; puis la flor s'épuise ou le vin est remuté à 17 %, et il poursuit en oxydation dans une solera d'Amontillado. Il réunit donc la pomme, l'amande et le pain de la flor aux épices, aux herbes et au tabac ; il est sec, au-dessus de 16 %, avec un corps léger puisque la flor a consommé le glycérol. Le Palo Cortado naît d'une base de qualité Fino qui n'a pas développé assez de flor : remuté à 17 %, il s'élève en oxydation. Il a le nez d'un Amontillado mais une bouche plus proche de l'Oloroso, 17–22 % et moins de 5 g/L de sucre ; ayant passé moins de temps sous flor, il garde plus de glycérol et paraît plus rond. Les deux phases n'ont pas de durée imposée, d'où des Amontillados très variés : les bon marché utilisent des vins jeunes des premières criaderas, les plus vieux et complexes vont du prix moyen au super-premium. Le Palo Cortado, rare, est en général très bon à exceptionnel et premium.",
         "The path begins at the press. Free run juice and the primera yema, low in phenolics, are used for biological wines, because phenolics hinder flor; the segunda yema, taken at higher pressure, usually goes to Oloroso. After fermentation each batch is tasted and analysed (first classification): the lightest, most delicate wines are fortified to 15–15.5%, the ideal alcohol for flor; fuller wines to 17%, at which flor cannot survive, and go straight into an Oloroso solera. Some months later the biological wines are re-examined (second classification): those with a full layer of flor that have stayed fresh become Fino or Manzanilla; those slightly less delicate are marked for Palo Cortado. Amontillado first passes through a Fino solera; then the flor dies away or the wine is refortified to 17%, and it continues oxidatively in an Amontillado solera. It therefore joins the apple, almond and bread of flor to spice, herbs and tobacco; it is dry, above 16%, and light in body because flor consumed the glycerol. Palo Cortado comes from a Fino-quality base that never developed enough flor: refortified to 17%, it ages oxidatively. It has the nose of an Amontillado but a palate closer to Oloroso, 17–22% and under 5 g/L of sugar; having spent less time under flor, it keeps more glycerol and feels rounder. Neither stage has a fixed length, so Amontillados vary widely: inexpensive ones use young wine from the youngest criaderas, while older, more complex ones range from mid-priced to super-premium. Palo Cortado, scarce, is usually very good to outstanding and premium-priced.",
         "El camino empieza en la prensa. El mosto yema y la primera yema, pobres en fenoles, se destinan a los vinos biológicos, porque los fenoles frenan la flor; la segunda yema, obtenida con más presión, suele ir al Oloroso. Tras la fermentación cada partida se cata y analiza (primera clasificación): los vinos más ligeros y delicados se encabezan a 15–15,5 %, el alcohol ideal para la flor; los más llenos a 17 %, nivel al que la flor no sobrevive, y entran directamente en una solera de Oloroso. Unos meses después los vinos biológicos se examinan de nuevo (segunda clasificación): los que tienen un velo de flor completo y siguen frescos serán Fino o Manzanilla; los algo menos delicados se destinan a Palo Cortado. El Amontillado pasa primero por una solera de Fino; luego la flor se agota o el vino se reencabeza a 17 %, y sigue oxidativamente en una solera de Amontillado. Une así la manzana, la almendra y el pan de la flor a especias, hierbas y tabaco; es seco, por encima del 16 %, y de cuerpo ligero porque la flor consumió el glicerol. El Palo Cortado nace de una base de calidad de Fino que no desarrolló bastante flor: reencabezado a 17 %, se cría oxidativamente. Tiene la nariz de un Amontillado pero una boca más cercana al Oloroso, 17–22 % y menos de 5 g/L de azúcar; al haber pasado menos tiempo bajo flor, conserva más glicerol y resulta más redondo. Ninguna fase tiene una duración fija, así que los Amontillados varían mucho: los económicos usan vinos jóvenes de las primeras criaderas y los más viejos y complejos van del precio medio al super-premium. El Palo Cortado, escaso, suele ser muy bueno o excepcional y premium."])]),
    Q("d5a", ["Non tutti gli Sherry dolci sono fatti allo stesso modo.", "Tous les Xérès doux ne sont pas élaborés de la même façon.", "Not all sweet Sherries are made the same way.", "No todos los Jereces dulces se elaboran igual."], [
      P(["Confronta la produzione di un PX, di un Pale Cream e di un Cream e spiega le differenze di stile, qualità e prezzo.", "Comparez l'élaboration d'un PX, d'un Pale Cream et d'un Cream et expliquez les différences de style, de qualité et de prix.", "Compare how a PX, a Pale Cream and a Cream are made and explain the differences in style, quality and price.", "Compara la elaboración de un PX, un Pale Cream y un Cream y explica las diferencias de estilo, calidad y precio."], 12,
        ["PX naturalmente dolce, nessun dolcificante aggiunto; uve appassite al sole per 2–3 settimane; fermentazione che si ferma a 4–6%, fortificato a 15–16%; maturazione ossidativa in una solera propria, l'evaporazione concentra; PX almeno 212 g/L, di solito 450–500; PX: uva passa, melassa, liquirizia, acidità bassa, sciropposo; uve PX anche da Montilla; dolcificati: Palomino fermentato a secco e fortificato, poi addolcito; Pale Cream: base biologica addolcita con mosto concentrato rettificato, senza colore; Pale Cream 45–115 g/L, economico, accettabile o buono; Cream: quasi sempre Oloroso addolcito con PX, 115–140 g/L; economici da vini giovani addolciti prima dell'imbottigliamento, premium addolciti e poi maturati in solera; vendite dei dolcificati più che dimezzate dal 2006, Regno Unito mercato principale",
         "PX naturellement doux, sans édulcorant ajouté ; raisins séchés au soleil 2 à 3 semaines ; fermentation qui s'arrête vers 4–6 %, muté à 15–16 % ; élevage oxydatif dans une solera propre, l'évaporation concentre ; PX au moins 212 g/L, en général 450–500 ; PX : raisins secs, mélasse, réglisse, acidité faible, sirupeux ; raisins PX aussi de Montilla ; vins adoucis : Palomino fermenté à sec et muté, puis adouci ; Pale Cream : base biologique adoucie au moût concentré rectifié, sans couleur ; Pale Cream 45–115 g/L, bon marché, acceptable à bon ; Cream : presque toujours un Oloroso adouci au PX, 115–140 g/L ; bon marché à partir de vins jeunes adoucis avant la mise, premium adoucis puis élevés en solera ; ventes des vins adoucis plus que divisées par deux depuis 2006, Royaume-Uni premier marché",
         "PX naturally sweet, no sweetener added; grapes sun-dried for 2–3 weeks; fermentation stops at 4–6%, fortified to 15–16%; oxidative ageing in its own solera, evaporation concentrates; PX at least 212 g/L, usually 450–500; PX: raisin, molasses, liquorice, low acidity, syrupy; PX grapes may also come from Montilla; sweetened wines: Palomino fermented dry and fortified, then sweetened; Pale Cream: biological base sweetened with rectified concentrated grape must, no colour; Pale Cream 45–115 g/L, inexpensive, acceptable to good; Cream: almost always Oloroso sweetened with PX, 115–140 g/L; inexpensive from young wines sweetened before bottling, premium sweetened then aged in a solera; sales of sweetened Sherries more than halved since 2006, UK the main market",
         "PX dulce natural, sin edulcorante añadido; uvas pasificadas al sol 2–3 semanas; fermentación que se detiene a 4–6 %, encabezado a 15–16 %; crianza oxidativa en su propia solera, la evaporación concentra; PX al menos 212 g/L, normalmente 450–500; PX: pasas, melaza, regaliz, acidez baja, siruposo; uvas PX también de Montilla; dulcificados: Palomino fermentado en seco y encabezado, luego dulcificado; Pale Cream: base biológica dulcificada con mosto concentrado rectificado, sin color; Pale Cream 45–115 g/L, económico, aceptable o bueno; Cream: casi siempre Oloroso dulcificado con PX, 115–140 g/L; económicos con vinos jóvenes dulcificados antes del embotellado, premium dulcificados y luego criados en solera; ventas de los dulcificados reducidas a menos de la mitad desde 2006, Reino Unido mercado principal"],
        ["Il PX è un vino naturalmente dolce: nessun dolcificante viene aggiunto. Le uve Pedro Ximénez, ricche di zucchero, sono stese al sole per 2–3 settimane; l'acqua evapora, lo zucchero si concentra e compaiono note di uva passa. Il mosto è così denso che la fermentazione si ferma da sola a 4–6%; il vino è fortificato a 15–16% e matura ossidativamente in una solera propria, dove l'evaporazione lo concentra ancora. Il minimo legale è 212 g/L, ma di solito si arriva a 450–500 g/L: un vino bruno, sciropposo, con uva passa, melassa e liquirizia e acidità bassa. Le uve possono venire anche dalla zona di Montilla. Va dall'economico al premium, di qualità da buona a eccezionale. Pale Cream e Cream sono invece dolcificati: si parte da Palomino fermentato a secco e fortificato, poi si aggiunge un componente dolce. Il Pale Cream deve aver fatto un periodo di invecchiamento biologico e viene addolcito con mosto concentrato rettificato, che non dà colore né aromi: resta chiaro, con un leggero tocco di flor, tra 45 e 115 g/L. Di solito è giovane, economico e di qualità accettabile o buona. Il Cream è quasi sempre un Oloroso addolcito con PX (talvolta con mosto rettificato) fino a 115–140 g/L: bruno, con noce e caramello sotto l'uva passa. Il prezzo dipende dall'età dei componenti: i vini economici sono giovani e addolciti poco prima dell'imbottigliamento; quelli premium sono assemblati e poi maturati ancora in una solera propria. È proprio la categoria dei dolcificati che ha perso più vendite, scese di oltre la metà dal 2006; il Regno Unito resta il loro mercato principale.",
         "Le PX est un vin naturellement doux : aucun édulcorant n'est ajouté. Les raisins de Pedro Ximénez, riches en sucre, sont étalés au soleil pendant 2 à 3 semaines ; l'eau s'évapore, le sucre se concentre et des notes de raisins secs apparaissent. Le moût est si dense que la fermentation s'arrête d'elle-même vers 4–6 % ; le vin est muté à 15–16 % et s'élève en oxydation dans une solera propre, où l'évaporation le concentre encore. Le minimum légal est de 212 g/L, mais on atteint en général 450–500 g/L : un vin brun, sirupeux, aux raisins secs, à la mélasse et à la réglisse, peu acide. Les raisins peuvent aussi venir de la zone de Montilla. Il va du bon marché au premium, de qualité bonne à exceptionnelle. Pale Cream et Cream sont au contraire des vins adoucis : on part d'un Palomino fermenté à sec et muté, puis on ajoute un élément doux. Le Pale Cream doit avoir connu une période d'élevage biologique et il est adouci au moût concentré rectifié, qui n'apporte ni couleur ni arômes : il reste clair, avec une légère touche de flor, entre 45 et 115 g/L. Il est en général jeune, bon marché et de qualité acceptable à bonne. Le Cream est presque toujours un Oloroso adouci au PX (parfois au moût rectifié) jusqu'à 115–140 g/L : brun, avec la noix et le caramel sous les raisins secs. Le prix dépend de l'âge des composants : les vins bon marché sont jeunes et adoucis peu avant la mise ; les premium sont assemblés puis encore élevés dans une solera propre. C'est justement la catégorie des vins adoucis qui a perdu le plus de ventes, plus que divisées par deux depuis 2006 ; le Royaume-Uni reste leur premier marché.",
         "PX is a naturally sweet wine: no sweetener is added. Sugar-rich Pedro Ximénez grapes are laid out in the sun for 2–3 weeks; water evaporates, sugar concentrates and raisin notes develop. The must is so dense that fermentation stops by itself at 4–6%; the wine is fortified to 15–16% and aged oxidatively in its own solera, where evaporation concentrates it further. The legal minimum is 212 g/L, but 450–500 g/L is usual: a brown, syrupy wine with raisin, molasses and liquorice and low acidity. The grapes may also come from the Montilla area. It ranges from inexpensive to premium and from good to outstanding quality. Pale Cream and Cream, by contrast, are sweetened: they start from Palomino fermented dry and fortified, and a sweet component is then added. Pale Cream must have undergone a period of biological ageing and is sweetened with rectified concentrated grape must, which adds neither colour nor flavour: it stays pale, with a light touch of flor, at 45–115 g/L. It is usually young, inexpensive and of acceptable to good quality. Cream is almost always an Oloroso sweetened with PX (sometimes with rectified must) to 115–140 g/L: brown, with walnut and caramel beneath the raisin. Price depends on the age of the components: inexpensive wines are young and sweetened shortly before bottling; premium ones are blended and then aged further in their own solera. It is precisely the sweetened category that has lost most sales, falling by more than half since 2006; the UK remains its main market.",
         "El PX es un vino dulce natural: no se añade ningún edulcorante. Las uvas Pedro Ximénez, ricas en azúcar, se extienden al sol durante 2–3 semanas; el agua se evapora, el azúcar se concentra y aparecen notas de pasas. El mosto es tan denso que la fermentación se detiene sola a 4–6 %; el vino se encabeza a 15–16 % y se cría oxidativamente en su propia solera, donde la evaporación lo concentra aún más. El mínimo legal es de 212 g/L, pero lo normal es llegar a 450–500 g/L: un vino marrón, siruposo, con pasas, melaza y regaliz y acidez baja. Las uvas pueden proceder también de la zona de Montilla. Va de económico a premium y de calidad buena a excepcional. Pale Cream y Cream son, en cambio, vinos dulcificados: se parte de Palomino fermentado en seco y encabezado, y después se añade un componente dulce. El Pale Cream debe haber pasado un periodo de crianza biológica y se dulcifica con mosto concentrado rectificado, que no aporta color ni aromas: queda pálido, con un ligero toque de flor, entre 45 y 115 g/L. Suele ser joven, económico y de calidad aceptable o buena. El Cream es casi siempre un Oloroso dulcificado con PX (a veces con mosto rectificado) hasta 115–140 g/L: marrón, con nuez y caramelo bajo las pasas. El precio depende de la edad de los componentes: los vinos económicos son jóvenes y se dulcifican poco antes del embotellado; los premium se mezclan y se crían después en su propia solera. Es justamente la categoría de los dulcificados la que más ventas ha perdido, reducidas a menos de la mitad desde 2006; el Reino Unido sigue siendo su mercado principal."])]),
    Q("d5a", ["Lo Sherry è uno dei vini più regolamentati al mondo, dal vigneto all'etichetta.", "Le Xérès est l'un des vins les plus réglementés au monde, de la vigne à l'étiquette.", "Sherry is one of the most closely regulated wines in the world, from vineyard to label.", "El Jerez es uno de los vinos más regulados del mundo, de la viña a la etiqueta."], [
      P(["Spiega come il Consejo Regulador, i registri delle bodegas e le indicazioni d'età influenzano qualità e prezzo dello Sherry.", "Expliquez comment le Consejo Regulador, les registres des bodegas et les mentions d'âge influencent la qualité et le prix du Xérès.", "Explain how the Consejo Regulador, the registers of bodegas and the age indications influence the quality and price of Sherry.", "Explica cómo el Consejo Regulador, los registros de bodegas y las indicaciones de edad influyen en la calidad y el precio del Jerez."], 10,
        ["Consejo Regulador, il primo registrato in Spagna nel 1933; fissa rese e alcol minimi, tiene i registri, controlla la rotazione delle scorte; promuove lo Sherry, per esempio con la International Sherry Week; bodegas de producción, cooperative comprese: pressano, fermentano, vendono vino base; almacenistas: maturano e conservano, vendono solo agli esportatori; bodegas de crianza y expedición: le sole autorizzate a vendere Sherry in bottiglia; nel 1996 scorta minima per esportare ridotta da 12.500 a 500 hL: alcuni almacenistas diventano esportatori; VOS almeno 20 anni di età media, VORS almeno 30; ogni lotto VOS e VORS assaggiato e analizzato, quota sulle scorte vendibili; 12 e 15 anni controllati per l'intera solera; volumi minimi, qualità molto buona o eccezionale, prezzi premium e super-premium; en rama definito nel 2021: al massimo filtrato, più intenso e più caro",
         "Consejo Regulador, le premier enregistré en Espagne en 1933 ; fixe rendements et alcool minimums, tient les registres, contrôle la rotation des stocks ; promeut le Xérès, par exemple avec l'International Sherry Week ; bodegas de producción, coopératives comprises : pressent, fermentent, vendent du vin de base ; almacenistas : élèvent et stockent, ne vendent qu'aux expéditeurs ; bodegas de crianza y expedición : seules autorisées à vendre du Xérès en bouteille ; en 1996 stock minimum pour expédier abaissé de 12 500 à 500 hL : certains almacenistas deviennent expéditeurs ; VOS au moins 20 ans d'âge moyen, VORS au moins 30 ; chaque lot VOS et VORS dégusté et analysé, quota sur les stocks vendables ; 12 et 15 ans contrôlés pour toute la solera ; volumes infimes, qualité très bonne à exceptionnelle, prix premium et super-premium ; en rama défini en 2021 : au plus filtré, plus intense et plus cher",
         "Consejo Regulador, the first registered in Spain, in 1933; sets maximum yields and minimum alcohol, keeps the registers, oversees stock rotation; promotes Sherry, for example through International Sherry Week; production bodegas, co-operatives included: press, ferment, sell base wine; almacenistas: age and store, may sell only to shippers; ageing and shipping bodegas: the only ones allowed to sell bottled Sherry; in 1996 minimum stock to ship cut from 12,500 to 500 hL: some almacenistas became shippers; VOS at least 20 years' average age, VORS at least 30; each VOS and VORS batch tasted and analysed, quota on saleable stock; 12- and 15-year-old checked for the whole solera; tiny volumes, very good to outstanding quality, premium and super-premium prices; en rama defined in 2021: at most filtered, more intense and dearer",
         "Consejo Regulador, el primero registrado en España, en 1933; fija rendimientos máximos y alcohol mínimo, lleva los registros, controla la rotación de existencias; promociona el Jerez, por ejemplo con la International Sherry Week; bodegas de producción, cooperativas incluidas: prensan, fermentan, venden vino base; almacenistas: crían y almacenan, solo venden a las bodegas exportadoras; bodegas de crianza y expedición: las únicas autorizadas a vender Jerez embotellado; en 1996 existencias mínimas para expedir reducidas de 12.500 a 500 hL: algunos almacenistas pasan a ser exportadores; VOS al menos 20 años de edad media, VORS al menos 30; cada lote VOS y VORS se cata y analiza, cupo sobre las existencias vendibles; 12 y 15 años controlados para toda la solera; volúmenes mínimos, calidad muy buena a excepcional, precios premium y super-premium; en rama definido en 2021: como mucho filtrado, más intenso y más caro"],
        ["Il Consejo Regulador dello Sherry, il primo registrato in Spagna (1933), fissa i parametri di produzione, come rese massime e alcol minimo dei vini base, tiene i registri dei vigneti e delle bodegas, controlla la rotazione delle scorte nelle soleras e certifica l'età dei vini; è anche un grande ente di promozione, con eventi come la International Sherry Week e corsi per professionisti. Le imprese sono iscritte in tre registri. Le bodegas de producción, comprese grandi cooperative, pressano e fermentano e vendono il vino base. Gli almacenistas maturano e conservano piccoli volumi, ma possono vendere solo alle bodegas de crianza y expedición, le uniche autorizzate a vendere Sherry in bottiglia. Così il valore aggiunto si concentra negli esportatori e nei loro marchi; con il calo delle vendite molti almacenistas hanno chiuso, finché nel 1996 la scorta minima per diventare esportatore è scesa da 12.500 a 500 hL e alcuni hanno potuto vendere con il proprio nome. Le indicazioni d'età sostengono la fascia alta: VOS significa un'età media di almeno 20 anni, VORS di almeno 30. Ogni lotto è assaggiato da una commissione e analizzato, ed è ammessa solo una piccola aggiunta di vino dolce, di solito PX, che non deve mascherare il carattere; un sistema di quote limita la parte delle scorte che si può vendere. Per i 12 e 15 anni il controllo riguarda l'intera solera. Volumi minimi e qualità molto buona o eccezionale spiegano prezzi premium e super-premium. Dal 2021 anche «en rama» ha una definizione: vini al massimo filtrati, senza altra stabilizzazione, più intensi e venduti più cari.",
         "Le Consejo Regulador du Xérès, le premier enregistré en Espagne (1933), fixe les paramètres de production, comme les rendements maximums et l'alcool minimum des vins de base, tient les registres des vignes et des bodegas, contrôle la rotation des stocks dans les soleras et certifie l'âge des vins ; c'est aussi un grand organe de promotion, avec des événements comme l'International Sherry Week et des formations pour les professionnels. Les entreprises sont inscrites dans trois registres. Les bodegas de producción, dont de grandes coopératives, pressent, fermentent et vendent du vin de base. Les almacenistas élèvent et stockent de petits volumes, mais ne peuvent vendre qu'aux bodegas de crianza y expedición, seules autorisées à vendre du Xérès en bouteille. La valeur ajoutée se concentre donc chez les expéditeurs et leurs marques ; avec la baisse des ventes, beaucoup d'almacenistas ont fermé, jusqu'à ce qu'en 1996 le stock minimum pour devenir expéditeur passe de 12 500 à 500 hL et que certains puissent vendre sous leur propre nom. Les mentions d'âge soutiennent le haut de gamme : VOS signifie un âge moyen d'au moins 20 ans, VORS d'au moins 30. Chaque lot est dégusté par un jury et analysé, et seul un petit ajout de vin doux, en général du PX, est permis, à condition de ne pas masquer le caractère ; un système de quotas limite la part des stocks qui peut être vendue. Pour les 12 et 15 ans, le contrôle porte sur toute la solera. Des volumes infimes et une qualité très bonne à exceptionnelle expliquent des prix premium et super-premium. Depuis 2021, « en rama » est défini : des vins tout au plus filtrés, sans autre stabilisation, plus intenses et vendus plus cher.",
         "Sherry's Consejo Regulador, the first registered in Spain (1933), sets production parameters such as maximum yields and minimum alcohol for base wines, keeps the vineyard and bodega registers, oversees stock rotation in the soleras and certifies the age of wines; it is also a major promotional body, with events such as International Sherry Week and courses for professionals. Businesses are listed in three registers. Production bodegas, including large co-operatives, press and ferment and sell base wine. Almacenistas age and store small volumes but may sell only to ageing and shipping bodegas, the only ones allowed to sell bottled Sherry. Added value is therefore concentrated in the shippers and their brands; as sales fell many almacenistas closed, until in 1996 the minimum stock to register as a shipper was cut from 12,500 to 500 hL and some could sell under their own name. Age indications support the top end: VOS means an average age of at least 20 years, VORS at least 30. Each batch is tasted by a panel and analysed, and only a small addition of sweet wine, usually PX, is allowed, provided it does not mask the character; a quota system limits the share of stock that may be sold. For 12- and 15-year-old wines the check covers the whole solera. Tiny volumes and very good to outstanding quality explain premium and super-premium prices. Since 2021 'en rama' has also been defined: wines at most filtered, with no other stabilisation, more intense and sold at higher prices.",
         "El Consejo Regulador del Jerez, el primero registrado en España (1933), fija los parámetros de producción, como los rendimientos máximos y el alcohol mínimo de los vinos base, lleva los registros de viñedos y bodegas, controla la rotación de existencias en las soleras y certifica la edad de los vinos; es además un gran organismo de promoción, con actos como la International Sherry Week y cursos para profesionales. Las empresas se inscriben en tres registros. Las bodegas de producción, incluidas grandes cooperativas, prensan, fermentan y venden vino base. Los almacenistas crían y almacenan pequeños volúmenes, pero solo pueden vender a las bodegas de crianza y expedición, las únicas autorizadas a vender Jerez embotellado. El valor añadido se concentra así en las bodegas exportadoras y sus marcas; con la caída de las ventas muchos almacenistas cerraron, hasta que en 1996 las existencias mínimas para inscribirse como exportador bajaron de 12.500 a 500 hL y algunos pudieron vender con su propio nombre. Las indicaciones de edad sostienen la gama alta: VOS significa una edad media de al menos 20 años, VORS de al menos 30. Cada lote lo cata un panel y se analiza, y solo se permite añadir un poco de vino dulce, normalmente PX, siempre que no enmascare el carácter; un sistema de cupos limita la parte de las existencias que puede venderse. En los de 12 y 15 años el control abarca toda la solera. Volúmenes mínimos y calidad muy buena o excepcional explican precios premium y super-premium. Desde 2021 «en rama» también tiene definición: vinos como mucho filtrados, sin otra estabilización, más intensos y vendidos más caros."])]),
    /* ---------- Port ---------- */
    Q("d5b", ["Un Porto rosso ha appena due giorni sulle bucce prima della fortificazione.", "Un Porto rouge n'a que deux jours sur les peaux avant le mutage.", "A red Port has only about two days on its skins before fortification.", "Un Oporto tinto tiene apenas dos días con los hollejos antes del encabezado."], [
      P(["Confronta i principali metodi di estrazione usati per il Porto e il loro effetto su stile, qualità e costi.", "Comparez les principales méthodes d'extraction utilisées pour le Porto et leur effet sur le style, la qualité et les coûts.", "Compare the main extraction methods used for Port and their effect on style, quality and cost.", "Compara los principales métodos de extracción usados para el Oporto y su efecto en el estilo, la calidad y los costes."], 8,
        ["macerazione al massimo di due giorni: estrazione rapida ed efficace; pigiatura a piedi in lagares bassi, circa 80 cm: delicata, non rompe i vinaccioli, per vini premium e super-premium; lagares robotizzati dal 2000, piedi di silicone: meno manodopera, costosi, qualità pari alla pigiatura a piedi; pistoni in acciaio, con rimontaggi, quasi altrettanto efficaci; rimontaggi da soli meno efficaci; autovinificatori dagli anni '60: niente elettricità, poca manodopera, economici; autovinificatori: poca estrazione, vini più chiari e leggeri, Ruby, Tawny e White di base; fermentazione a 28–32 °C, fermata a 5–7% con 80–120 g/L",
         "macération de deux jours au plus : extraction rapide et efficace ; foulage au pied en lagares peu profonds, environ 80 cm : doux, n'écrase pas les pépins, pour les vins premium et super-premium ; lagares robotisés depuis 2000, pieds en silicone : moins de main-d'œuvre, coûteux, qualité égale au foulage au pied ; pistons en inox, avec remontages, presque aussi efficaces ; remontages seuls moins efficaces ; autovinificateurs depuis les années 1960 : sans électricité, peu de main-d'œuvre, bon marché ; autovinificateurs : peu d'extraction, vins plus clairs et légers, Ruby, Tawny et White de base ; fermentation à 28–32 °C, arrêtée à 5–7 % avec 80–120 g/L",
         "maceration of two days at most: extraction must be fast and effective; foot treading in shallow lagares, about 80 cm: gentle, does not crush seeds, for premium and super-premium wines; robotic lagares since 2000, silicone feet: less labour, expensive, quality equal to foot treading; stainless steel pistons, with pumping over, almost as effective; pumping over alone less effective; autovinifiers since the 1960s: no electricity, little labour, cheap; autovinifiers: little extraction, paler and lighter wines, basic Ruby, Tawny and White; fermentation at 28–32 °C, stopped at 5–7% with 80–120 g/L",
         "maceración de dos días como máximo: extracción rápida y eficaz; pisado a pie en lagares poco profundos, unos 80 cm: suave, no rompe las pepitas, para vinos premium y super-premium; lagares robotizados desde 2000, pies de silicona: menos mano de obra, caros, calidad igual al pisado a pie; pistones de acero, con remontados, casi igual de eficaces; remontados solos menos eficaces; autovinificadores desde los años 60: sin electricidad, poca mano de obra, baratos; autovinificadores: poca extracción, vinos más pálidos y ligeros, Ruby, Tawny y White básicos; fermentación a 28–32 °C, detenida a 5–7 % con 80–120 g/L"],
        ["Il Porto è fortificato quando il mosto ha 5–7% di alcol, per conservare 80–120 g/L di zucchero: la macerazione dura al massimo due giorni, quindi l'estrazione di colore e tannino deve essere rapida, efficace ma delicata. Le fermentazioni a 28–32 °C bastano a estrarre senza correre troppo. La pigiatura a piedi nei lagares, vasche basse di circa 80 cm con una grande superficie di contatto, è efficacissima e non schiaccia i vinaccioli, evitando tannini amari; costa però molta manodopera in una regione che si spopola, e oggi è riservata a pochi Porto premium e super-premium. I lagares robotizzati, in uso dal 2000, premono le uve con piedi di silicone montati su un ponte d'acciaio e poi follano il cappello: danno qualità pari alla pigiatura a piedi con poca manodopera, ma l'investimento è alto. Le vasche aperte con pistoni programmati, spesso abbinati a rimontaggi, sono quasi altrettanto efficaci; i soli rimontaggi danno vini colorati ma estraggono meno. Gli autovinificatori, introdotti negli anni '60, usano la pressione della CO₂ per spruzzare il mosto sul cappello: niente elettricità, pochissimo lavoro, costo basso, ma l'estrazione comincia solo quando la fermentazione è avviata, quindi i vini sono più chiari, leggeri e meno intensi. Servono per Ruby, Tawny e White di base, mentre lagares e pistoni si usano per i vini destinati all'invecchiamento, come i Vintage.",
         "Le Porto est muté quand le moût atteint 5–7 % d'alcool, pour garder 80–120 g/L de sucre : la macération dure deux jours au plus, l'extraction de la couleur et du tanin doit donc être rapide, efficace mais douce. Des fermentations à 28–32 °C suffisent à extraire sans aller trop vite. Le foulage au pied dans les lagares, cuves basses d'environ 80 cm offrant une grande surface de contact, est très efficace et n'écrase pas les pépins, ce qui évite les tanins amers ; mais il exige beaucoup de main-d'œuvre dans une région qui se dépeuple, et il est aujourd'hui réservé à quelques Portos premium et super-premium. Les lagares robotisés, utilisés depuis 2000, pressent les raisins avec des pieds en silicone montés sur un portique en inox puis pigent le chapeau : ils donnent une qualité égale au foulage au pied avec peu de main-d'œuvre, mais l'investissement est lourd. Les cuves ouvertes à pistons programmés, souvent associés à des remontages, sont presque aussi efficaces ; les remontages seuls donnent des vins colorés mais extraient moins. Les autovinificateurs, introduits dans les années 1960, utilisent la pression du CO₂ pour arroser le chapeau : pas d'électricité, très peu de travail, coût bas, mais l'extraction ne commence qu'une fois la fermentation lancée, d'où des vins plus clairs, légers et moins intenses. Ils servent aux Ruby, Tawny et White de base, tandis que lagares et pistons sont utilisés pour les vins de garde comme les Vintage.",
         "Port is fortified when the must reaches 5–7% abv, to keep 80–120 g/L of sugar: maceration lasts two days at most, so extraction of colour and tannin must be fast, effective yet gentle. Fermentation at 28–32 °C is warm enough to extract without racing ahead. Foot treading in lagares, shallow tanks about 80 cm deep with a large contact surface, is highly effective and does not crush seeds, avoiding bitter tannins; but it needs a lot of labour in a depopulating region, and today is kept for a few premium and super-premium Ports. Robotic lagares, used since 2000, press the grapes with silicone feet on a stainless steel gantry and then punch down the cap: they give quality equal to foot treading with little labour, but the investment is high. Open tanks with programmed pistons, often combined with pumping over, are almost as effective; pumping over alone gives coloured wines but extracts less. Autovinifiers, introduced in the 1960s, use CO₂ pressure to spray must over the cap: no electricity, very little work, low cost, but extraction starts only once fermentation is under way, so the wines are paler, lighter and less intense. They are used for basic Ruby, Tawny and White, while lagares and pistons are used for wines meant to age, such as Vintage.",
         "El Oporto se encabeza cuando el mosto tiene 5–7 % de alcohol, para conservar 80–120 g/L de azúcar: la maceración dura dos días como máximo, así que la extracción de color y tanino debe ser rápida, eficaz y a la vez suave. Fermentar a 28–32 °C basta para extraer sin que la fermentación corra demasiado. El pisado a pie en lagares, depósitos bajos de unos 80 cm con una gran superficie de contacto, es muy eficaz y no rompe las pepitas, lo que evita taninos amargos; pero exige mucha mano de obra en una región que se despuebla, y hoy se reserva a unos pocos Oportos premium y super-premium. Los lagares robotizados, en uso desde 2000, prensan la uva con pies de silicona montados en un pórtico de acero y luego bazuquean el sombrero: dan una calidad igual al pisado a pie con poca mano de obra, pero la inversión es alta. Los depósitos abiertos con pistones programados, a menudo combinados con remontados, son casi igual de eficaces; los remontados solos dan vinos con color pero extraen menos. Los autovinificadores, introducidos en los años 60, usan la presión del CO₂ para regar el sombrero: sin electricidad, muy poco trabajo y coste bajo, pero la extracción solo empieza cuando la fermentación está en marcha, así que los vinos son más pálidos, ligeros y menos intensos. Se usan para Ruby, Tawny y White básicos, mientras que lagares y pistones se reservan a vinos de guarda como los Vintage."]),
      P(["Spiega il ruolo dello spirito di fortificazione nello stile e nella qualità del Porto.", "Expliquez le rôle de l'eau-de-vie de mutage dans le style et la qualité du Porto.", "Explain the role of the fortifying spirit in the style and quality of Port.", "Explica el papel del aguardiente de encabezado en el estilo y la calidad del Oporto."], 6,
        ["aguardente d'uva al 77% (±0,5%), non neutra; circa 1 litro di spirito ogni 4 litri di mosto per arrivare al 20%; Porto fortificato a 19–22%, i Porto di base almeno 18%; più carattere e note spiritose rispetto agli spiriti al 95–96%; dal 1991 i produttori scelgono e comprano il proprio spirito: qualità migliorata; spiriti neutri o aromatici, di qualità e prezzo diversi: i migliori per i Porto premium, uno neutro per il Rosé",
         "aguardente de raisin à 77 % (±0,5 %), non neutre ; environ 1 litre d'eau-de-vie pour 4 litres de moût pour atteindre 20 % ; Porto muté à 19–22 %, Portos de base au moins 18 % ; plus de caractère et des notes spiritueuses que les alcools à 95–96 % ; depuis 1991 les producteurs choisissent et achètent leur eau-de-vie : qualité améliorée ; eaux-de-vie neutres ou aromatiques, de qualités et prix différents : les meilleures pour les Portos premium, une neutre pour le Rosé",
         "grape aguardente at 77% (±0.5%), not neutral; about 1 litre of spirit for every 4 litres of must to reach 20%; Port fortified to 19–22%, basic Ports at least 18%; more character and spirity notes than 95–96% spirits; since 1991 producers choose and buy their own spirit: quality improved; neutral or aromatic spirits of different qualities and prices: the best for premium Ports, a neutral one for Rosé",
         "aguardiente de uva al 77 % (±0,5 %), no neutro; alrededor de 1 litro de aguardiente por cada 4 litros de mosto para llegar al 20 %; Oporto encabezado a 19–22 %, los básicos al menos 18 %; más carácter y notas espirituosas que los alcoholes de 95–96 %; desde 1991 los productores eligen y compran su aguardiente: la calidad mejoró; aguardientes neutros o aromáticos, de calidades y precios distintos: los mejores para los Oportos premium, uno neutro para el Rosé"],
        ["La legge impone un'aguardente di origine viticola al 77% (±0,5%), molto meno alcolica dei distillati neutri al 95–96% usati per gli altri fortificati. Per portare il mosto a circa il 20% serve quindi un volume alto, circa un litro di spirito ogni quattro di mosto, e uno spirito a quel grado conserva aromi propri: per questo il Porto può mostrare note spiritose e la qualità dello spirito pesa molto sul vino finito. La maggior parte dei Porto è fortificata a 19–22%; Ruby, Tawny, White e Rosé di base possono fermarsi al 18%. Fino agli anni '90 tutti dovevano usare la stessa aguardente, comprata tramite la Casa do Douro e poi tramite gare dell'IVP, di qualità modesta. Dal 1991 i produttori comprano liberamente il proprio spirito e la qualità del Porto è migliorata. Oggi scelgono spiriti più neutri, che lasciano parlare il vino, o più aromatici, con esteri fruttati; spiriti migliori e più cari per i Porto premium, più economici per i vini di base; per il Rosé, più delicato, uno spirito neutro e di alta qualità che non copra il frutto.",
         "La loi impose une aguardente d'origine viticole à 77 % (±0,5 %), bien moins alcoolique que les alcools neutres à 95–96 % utilisés pour les autres vins mutés. Pour amener le moût vers 20 %, il faut donc un volume élevé, environ un litre d'eau-de-vie pour quatre de moût, et une eau-de-vie à ce degré garde des arômes propres : c'est pourquoi le Porto peut montrer des notes spiritueuses et pourquoi la qualité de l'eau-de-vie pèse lourd sur le vin fini. La plupart des Portos sont mutés à 19–22 % ; Ruby, Tawny, White et Rosé de base peuvent s'arrêter à 18 %. Jusqu'aux années 1990, tous devaient utiliser la même aguardente, achetée par la Casa do Douro puis par appel d'offres de l'IVP, de qualité modeste. Depuis 1991, les producteurs achètent librement leur eau-de-vie et la qualité du Porto s'est améliorée. Ils choisissent aujourd'hui des eaux-de-vie plus neutres, qui laissent parler le vin, ou plus aromatiques, aux esters fruités ; des eaux-de-vie meilleures et plus chères pour les Portos premium, plus économiques pour les vins de base ; pour le Rosé, plus délicat, une eau-de-vie neutre et de grande qualité qui ne masque pas le fruit.",
         "The law requires a grape-derived aguardente at 77% (±0.5%), much weaker than the 95–96% neutral spirits used for other fortified wines. Bringing the must to about 20% therefore needs a large volume, roughly one litre of spirit for every four of must, and a spirit at that strength keeps aromas of its own: this is why Port can show spirity notes and why the quality of the spirit weighs heavily on the finished wine. Most Ports are fortified to 19–22%; basic Ruby, Tawny, White and Rosé may stop at 18%. Until the 1990s everyone had to use the same aguardente, bought through the Casa do Douro and then by IVP tender, of modest quality. Since 1991 producers have been free to buy their own spirit, and Port quality has improved. Today they choose more neutral spirits, which let the wine speak, or more aromatic ones with fruity esters; better, dearer spirits for premium Ports, cheaper ones for basic wines; and for the more delicate Rosé, a neutral, high-quality spirit that does not mask the fruit.",
         "La ley exige un aguardiente de origen vínico al 77 % (±0,5 %), mucho menos alcohólico que los alcoholes neutros de 95–96 % usados para los otros generosos. Para llevar el mosto a un 20 % hace falta, por tanto, un volumen alto, cerca de un litro de aguardiente por cada cuatro de mosto, y un aguardiente a esa graduación conserva aromas propios: por eso el Oporto puede mostrar notas espirituosas y la calidad del aguardiente pesa mucho en el vino final. La mayoría de los Oportos se encabeza a 19–22 %; Ruby, Tawny, White y Rosé básicos pueden quedarse en el 18 %. Hasta los años 90 todos debían usar el mismo aguardiente, comprado a través de la Casa do Douro y luego por concurso del IVP, de calidad modesta. Desde 1991 los productores compran libremente su aguardiente y la calidad del Oporto ha mejorado. Hoy eligen aguardientes más neutros, que dejan hablar al vino, o más aromáticos, con ésteres afrutados; mejores y más caros para los Oportos premium, más baratos para los vinos básicos; y para el Rosé, más delicado, uno neutro y de gran calidad que no tape la fruta."])]),
    Q("d5b", ["Ruby Reserve, LBV, Crusted, Single Quinta e Vintage sono tutti Porto di stile Ruby.", "Ruby Reserve, LBV, Crusted, Single Quinta et Vintage sont tous des Portos de style Ruby.", "Reserve Ruby, LBV, Crusted, Single Quinta and Vintage are all Ruby-style Ports.", "Ruby Reserve, LBV, Crusted, Single Quinta y Vintage son todos Oportos de estilo Ruby."], [
      P(["Spiega come le scelte di produzione e di maturazione distinguono queste categorie per stile, qualità, prezzo e attitudine all'invecchiamento in bottiglia.", "Expliquez comment les choix d'élaboration et d'élevage distinguent ces catégories par le style, la qualité, le prix et l'aptitude à la garde en bouteille.", "Explain how production and maturation choices distinguish these categories in style, quality, price and suitability for bottle ageing.", "Explica cómo las decisiones de elaboración y crianza distinguen estas categorías en estilo, calidad, precio y aptitud para la guarda en botella."], 12,
        ["Ruby di base: massimo 3 anni in grandi recipienti, frutto semplice, economico; Reserve Ruby: nessuna età minima, più concentrato, approvato dalla commissione dell'IVDP; LBV: una sola annata, imbottigliato 4–6 anni dopo la vendemmia, in grandi botti o acciaio; LBV per lo più filtrato, pronto, buono o molto buono, prezzo medio; LBV non filtrato: più pieno, migliora in bottiglia, «bottle matured» dopo 3 anni in bottiglia; Crusted: più annate, fino a 2 anni in botte, non chiarificato né filtrato, deposito, data di imbottigliamento in etichetta; Vintage: solo annate dichiarate, circa 3–4 su 10, approvate dall'IVDP; Vintage: vigneti meglio classificati, Touriga Nacional e Franca, forte estrazione; Vintage: al massimo 3 anni in legno, di solito 18–20 mesi, non filtrato, lungo invecchiamento in bottiglia; Vintage molto buono o eccezionale, premium o super-premium, redditizio perché venduto presto; Single Quinta: un'annata e una sola tenuta, negli anni non dichiarati",
         "Ruby de base : 3 ans au plus en grands contenants, fruit simple, bon marché ; Reserve Ruby : pas d'âge minimum, plus concentré, approuvé par le jury de l'IVDP ; LBV : un seul millésime, mis en bouteille 4 à 6 ans après la vendange, en grands foudres ou en inox ; LBV le plus souvent filtré, prêt, bon à très bon, prix moyen ; LBV non filtré : plus ample, progresse en bouteille, « bottle matured » après 3 ans de bouteille ; Crusted : plusieurs millésimes, jusqu'à 2 ans en fût, ni collé ni filtré, dépôt, date de mise sur l'étiquette ; Vintage : seulement les millésimes déclarés, environ 3 à 4 sur 10, approuvés par l'IVDP ; Vintage : vignes les mieux classées, Touriga Nacional et Franca, forte extraction ; Vintage : 3 ans au plus sous bois, en général 18 à 20 mois, non filtré, longue garde en bouteille ; Vintage très bon à exceptionnel, premium ou super-premium, rentable car vendu tôt ; Single Quinta : un millésime et un seul domaine, les années non déclarées",
         "basic Ruby: at most 3 years in large vessels, simple fruit, inexpensive; Reserve Ruby: no minimum age, more concentrated, approved by the IVDP panel; LBV: single year, bottled 4–6 years after harvest, in large casks or steel; LBV mostly filtered, ready, good to very good, mid-priced; unfiltered LBV: fuller, improves in bottle, 'bottle matured' after 3 years in bottle; Crusted: several vintages, up to 2 years in cask, unfined and unfiltered, deposit, bottling date on the label; Vintage: declared years only, about 3–4 in 10, approved by the IVDP; Vintage: best-graded vineyards, Touriga Nacional and Franca, high extraction; Vintage: at most 3 years in wood, usually 18–20 months, unfiltered, long bottle ageing; Vintage very good to outstanding, premium or super-premium, profitable because sold early; Single Quinta: one year and one estate, in undeclared years",
         "Ruby básico: como máximo 3 años en recipientes grandes, fruta sencilla, económico; Reserve Ruby: sin edad mínima, más concentrado, aprobado por el panel del IVDP; LBV: una sola añada, embotellado 4–6 años tras la vendimia, en toneles grandes o acero; LBV casi siempre filtrado, listo, bueno o muy bueno, precio medio; LBV sin filtrar: más lleno, mejora en botella, «bottle matured» tras 3 años en botella; Crusted: varias añadas, hasta 2 años en barrica, sin clarificar ni filtrar, depósito, fecha de embotellado en la etiqueta; Vintage: solo añadas declaradas, unas 3–4 de cada 10, aprobadas por el IVDP; Vintage: viñedos mejor clasificados, Touriga Nacional y Franca, fuerte extracción; Vintage: como máximo 3 años en madera, normalmente 18–20 meses, sin filtrar, larga guarda en botella; Vintage muy bueno o excepcional, premium o super-premium, rentable porque se vende pronto; Single Quinta: una añada y una sola finca, en los años no declarados"],
        ["Tutti questi vini puntano sul frutto e limitano l'ossidazione, ma differiscono per materia prima, tempo e modo di maturazione. Il Ruby di base matura al massimo tre anni in grandi vasche o in vecchi tini da 10.000–100.000 litri, è un assemblaggio di annate, semplice e fruttato, economico. Il Reserve Ruby non ha un'età minima ma è più concentrato e deve essere approvato dalla commissione di degustazione dell'IVDP. L'LBV viene da una sola annata e si imbottiglia tra quattro e sei anni dopo la vendemmia, dopo una maturazione in grandi botti vecchie o in acciaio: le uve sono meno pregiate di quelle del Vintage e il lungo affinamento in massa lo rende pronto; per lo più è filtrato, non va decantato, è buono o molto buono e di prezzo medio. Gli LBV non filtrati sono più pieni e possono migliorare in bottiglia; dopo tre anni in bottiglia prima della vendita possono riportare «bottle matured». Il Crusted assembla più annate, resta fino a due anni in botte ed è imbottigliato senza chiarifica né filtrazione: forma una «crosta» di deposito, riporta la data di imbottigliamento, somiglia al Vintage e invecchia bene a un prezzo medio o premium. Il Vintage nasce solo nelle annate dichiarate, circa tre o quattro su dieci, registrate nel secondo anno e approvate dall'IVDP: uve dei vigneti meglio classificati, con Touriga Nacional e Touriga Franca, estrazione intensa, al massimo tre anni (di solito 18–20 mesi) in legno e poi decenni in bottiglia, senza filtrazione. È molto buono o eccezionale, premium o super-premium, e redditizio perché si vende presto. Negli anni non dichiarati, il Single Quinta offre un vino di un'annata e di una sola tenuta, come Quinta de Vargellas.",
         "Tous ces vins misent sur le fruit et limitent l'oxydation, mais ils diffèrent par la matière première, la durée et le mode d'élevage. Le Ruby de base s'élève trois ans au plus en grandes cuves ou en vieux foudres de 10 000 à 100 000 litres ; c'est un assemblage de millésimes, simple et fruité, bon marché. Le Reserve Ruby n'a pas d'âge minimum mais il est plus concentré et doit être approuvé par le jury de dégustation de l'IVDP. Le LBV provient d'un seul millésime et se met en bouteille entre quatre et six ans après la vendange, après un élevage en grands foudres anciens ou en inox : les raisins sont moins prestigieux que ceux du Vintage et le long élevage en masse le rend prêt à boire ; le plus souvent filtré, il ne demande pas de carafage, il est bon à très bon et de prix moyen. Les LBV non filtrés sont plus amples et peuvent progresser en bouteille ; après trois ans de bouteille avant la vente, ils peuvent porter « bottle matured ». Le Crusted assemble plusieurs millésimes, reste jusqu'à deux ans en fût et est mis en bouteille sans collage ni filtration : il forme une « croûte » de dépôt, porte la date de mise, ressemble au Vintage et vieillit bien, à un prix moyen ou premium. Le Vintage ne naît que les années déclarées, environ trois ou quatre sur dix, enregistrées la deuxième année et approuvées par l'IVDP : raisins des vignes les mieux classées, avec Touriga Nacional et Touriga Franca, extraction intense, trois ans au plus (en général 18 à 20 mois) sous bois puis des décennies en bouteille, sans filtration. Il est très bon à exceptionnel, premium ou super-premium, et rentable car vendu tôt. Les années non déclarées, le Single Quinta offre un vin d'un millésime et d'un seul domaine, comme Quinta de Vargellas.",
         "All these wines focus on fruit and limit oxidation, but they differ in raw material, time and type of maturation. Basic Ruby matures for at most three years in large tanks or old vats of 10,000–100,000 litres; it is a blend of years, simple and fruity, inexpensive. Reserve Ruby has no minimum age but is more concentrated and must be approved by the IVDP tasting panel. LBV comes from a single year and is bottled four to six years after harvest, after maturation in large old casks or steel: the grapes are of lower quality than those for Vintage and the long bulk ageing makes it ready to drink; mostly filtered, it needs no decanting, is good to very good and mid-priced. Unfiltered LBVs are fuller and can improve in bottle; after three years in bottle before release they may be labelled 'bottle matured'. Crusted blends several vintages, spends up to two years in cask and is bottled without fining or filtration: it throws a 'crust' of deposit, states the bottling date, resembles Vintage and ages well at mid to premium prices. Vintage is made only in declared years, about three or four in ten, registered in the second year and approved by the IVDP: grapes from the best-graded vineyards, with Touriga Nacional and Touriga Franca, intense extraction, at most three years (usually 18–20 months) in wood and then decades in bottle, unfiltered. It is very good to outstanding, premium or super-premium, and profitable because it is sold early. In undeclared years, Single Quinta offers a wine from one year and one estate, such as Quinta de Vargellas.",
         "Todos estos vinos apuestan por la fruta y limitan la oxidación, pero difieren en materia prima, tiempo y modo de crianza. El Ruby básico se cría como máximo tres años en depósitos grandes o en viejos toneles de 10.000–100.000 litros; es una mezcla de añadas, sencillo y afrutado, económico. El Reserve Ruby no tiene edad mínima pero es más concentrado y debe aprobarlo el panel de cata del IVDP. El LBV procede de una sola añada y se embotella entre cuatro y seis años tras la vendimia, después de criarse en toneles grandes y viejos o en acero: la uva es de menor calidad que la del Vintage y la larga crianza a granel lo deja listo para beber; casi siempre filtrado, no necesita decantación, es bueno o muy bueno y de precio medio. Los LBV sin filtrar son más llenos y pueden mejorar en botella; tras tres años en botella antes de la venta pueden indicar «bottle matured». El Crusted mezcla varias añadas, pasa hasta dos años en barrica y se embotella sin clarificar ni filtrar: forma una «costra» de depósito, indica la fecha de embotellado, se parece al Vintage y envejece bien, a precio medio o premium. El Vintage solo se elabora en añadas declaradas, unas tres o cuatro de cada diez, registradas el segundo año y aprobadas por el IVDP: uva de los viñedos mejor clasificados, con Touriga Nacional y Touriga Franca, extracción intensa, como máximo tres años (normalmente 18–20 meses) en madera y luego décadas en botella, sin filtrar. Es muy bueno o excepcional, premium o super-premium, y rentable porque se vende pronto. En los años no declarados, el Single Quinta ofrece un vino de una añada y una sola finca, como Quinta de Vargellas."])]),
    Q("d5b", ["Le vendite di Porto calano dal 2000, ma il prezzo medio sale.", "Les ventes de Porto baissent depuis 2000, mais le prix moyen augmente.", "Port sales have been falling since 2000, yet the average price is rising.", "Las ventas de Oporto caen desde 2000, pero el precio medio sube."], [
      P(["Descrivi la struttura del settore del Porto e valuta le strategie dei produttori per rispondere al calo dei volumi.", "Décrivez la structure du secteur du Porto et évaluez les stratégies des producteurs face à la baisse des volumes.", "Describe the structure of the Port industry and evaluate the strategies producers are using in response to falling volumes.", "Describe la estructura del sector del Oporto y valora las estrategias de los productores ante la caída de los volúmenes."], 10,
        ["circa 20.000 proprietari, in media 2,2 ettari; quasi tutti vendono uve a produttori o cooperative; cooperative circa 20% del vino, vendono soprattutto ai produttori; 30–35 produttori importanti, i primi cinque fanno l'80% dei volumi; gruppi: Gran Cruz, Symington, Sogrape, Fladgate, Sogevinus; IVDP: vendibile al massimo un terzo delle scorte, degustazione delle categorie, promozione; nel 2022 circa 80 milioni di litri prodotti, 70 venduti, 82% esportati; Francia primo mercato, Porto economici da aperitivo in calo; categorie speciali 23% dei volumi ma 45% del valore; Tawny con indicazione d'età e grandi formati per la ristorazione; Rosé e White Port con tonica, cocktail, nuovi consumatori; vini fermi del Douro (Symington, Noval, Niepoort) o specializzazione nel Porto (Taylor's)",
         "environ 20 000 propriétaires, 2,2 hectares en moyenne ; presque tous vendent leurs raisins aux producteurs ou aux coopératives ; coopératives environ 20 % du vin, vendent surtout aux producteurs ; 30 à 35 producteurs importants, les cinq premiers font 80 % des volumes ; groupes : Gran Cruz, Symington, Sogrape, Fladgate, Sogevinus ; IVDP : un tiers des stocks au plus vendable, dégustation des catégories, promotion ; en 2022 environ 80 millions de litres produits, 70 vendus, 82 % exportés ; France premier marché, Portos bon marché d'apéritif en baisse ; catégories spéciales 23 % des volumes mais 45 % de la valeur ; Tawny avec mention d'âge et grands formats pour la restauration ; Rosé et White Port tonic, cocktails, nouveaux consommateurs ; vins tranquilles du Douro (Symington, Noval, Niepoort) ou spécialisation dans le Porto (Taylor's)",
         "about 20,000 owners, 2.2 hectares on average; nearly all sell grapes to producers or co-operatives; co-operatives about 20% of the wine, sell mostly to producers; 30–35 significant producers, the top five make 80% of volume; groups: Gran Cruz, Symington, Sogrape, Fladgate, Sogevinus; IVDP: at most one-third of stocks saleable, tasting of categories, promotion; in 2022 about 80 million litres produced, 70 sold, 82% exported; France the largest market, inexpensive aperitif Ports declining; special categories 23% of volume but 45% of value; age-indicated Tawny and large formats for hospitality; Rosé and White Port and tonic, cocktails, new consumers; unfortified Douro wines (Symington, Noval, Niepoort) or Port specialism (Taylor's)",
         "unos 20.000 propietarios, 2,2 hectáreas de media; casi todos venden la uva a productores o cooperativas; cooperativas alrededor del 20 % del vino, venden sobre todo a los productores; 30–35 productores importantes, los cinco primeros hacen el 80 % del volumen; grupos: Gran Cruz, Symington, Sogrape, Fladgate, Sogevinus; IVDP: vendible como máximo un tercio de las existencias, cata de las categorías, promoción; en 2022 unos 80 millones de litros producidos, 70 vendidos, 82 % exportados; Francia primer mercado, Oportos económicos de aperitivo en descenso; categorías especiales 23 % del volumen pero 45 % del valor; Tawny con indicación de edad y grandes formatos para hostelería; Rosé y White Port con tónica, cócteles, nuevos consumidores; vinos tranquilos del Duero (Symington, Noval, Niepoort) o especialización en Oporto (Taylor's)"],
        ["La proprietà dei vigneti è frammentatissima: circa 20.000 proprietari con 2,2 ettari in media, che vendono quasi tutti le uve a produttori medi e grandi o a cooperative. Le cooperative fanno circa il 20% del vino ma, data la forza dei marchi degli esportatori, lo vendono per lo più ai produttori; spesso intervengono dei mediatori. A valle il settore è molto concentrato: solo 30–35 produttori contano davvero e i primi cinque, cioè Gran Cruz, Symington Family Estates, Sogrape, The Fladgate Partnership e Sogevinus, fanno l'80% dei volumi. L'IVDP regola la produzione con il beneficio, limita le vendite annuali a un terzo delle scorte di ciascun produttore, assaggia i vini delle diverse categorie e promuove Porto e vini del Douro. Nel 2022 si sono prodotti circa 80 milioni di litri e venduti 70, per l'82% all'estero. Il calo viene dai Porto economici bevuti come aperitivo in Francia, primo mercato, e nei Paesi Bassi, dove altre bevande li sostituiscono. Le categorie speciali (Reserve, LBV, Vintage, Tawny con indicazione d'età e altre) valgono il 23% dei volumi ma il 45% del valore, ed è su di esse che si punta: Tawny invecchiati, sempre più richiesti, e perfino formati da 4,5 litri per la ristorazione. Per attirare nuovi consumatori si propongono il Rosé e il White Port con tonica, anche in cocktail, con un alcol più basso di molti superalcolici. Infine alcuni diversificano nei vini fermi del Douro, come Symington, Quinta do Noval, Ramos Pinto e Niepoort, mentre Taylor's ha puntato sulla specializzazione nel Porto. La premiumizzazione protegge i margini, ma non sostituisce del tutto i volumi persi.",
         "La propriété des vignes est très morcelée : environ 20 000 propriétaires avec 2,2 hectares en moyenne, qui vendent presque tous leurs raisins à des producteurs moyens et grands ou à des coopératives. Les coopératives font environ 20 % du vin mais, vu la force des marques des expéditeurs, le vendent surtout aux producteurs ; des courtiers interviennent souvent. En aval, le secteur est très concentré : seuls 30 à 35 producteurs comptent vraiment et les cinq premiers, Gran Cruz, Symington Family Estates, Sogrape, The Fladgate Partnership et Sogevinus, font 80 % des volumes. L'IVDP régule la production par le beneficio, limite les ventes annuelles au tiers des stocks de chaque producteur, déguste les vins des différentes catégories et promeut Porto et vins du Douro. En 2022, environ 80 millions de litres ont été produits et 70 vendus, à 82 % à l'export. La baisse vient des Portos bon marché bus à l'apéritif en France, premier marché, et aux Pays-Bas, où d'autres boissons les remplacent. Les catégories spéciales (Reserve, LBV, Vintage, Tawny avec mention d'âge et autres) représentent 23 % des volumes mais 45 % de la valeur, et c'est sur elles que l'on mise : Tawny âgés, de plus en plus demandés, et même des formats de 4,5 litres pour la restauration. Pour attirer de nouveaux consommateurs, on propose le Rosé et le White Port tonic, aussi en cocktails, avec un alcool plus faible que bien des spiritueux. Enfin, certains se diversifient dans les vins tranquilles du Douro, comme Symington, Quinta do Noval, Ramos Pinto et Niepoort, tandis que Taylor's a misé sur la spécialisation dans le Porto. La montée en gamme protège les marges, mais ne compense pas entièrement les volumes perdus.",
         "Vineyard ownership is highly fragmented: about 20,000 owners with 2.2 hectares on average, nearly all of whom sell their grapes to medium and large producers or to co-operatives. Co-operatives make about 20% of the wine but, given the strength of the shippers' brands, sell most of it to producers; brokers are often involved. Downstream the industry is very concentrated: only 30–35 producers really count, and the top five, Gran Cruz, Symington Family Estates, Sogrape, The Fladgate Partnership and Sogevinus, make 80% of volume. The IVDP regulates production through the beneficio, limits each producer's annual sales to one-third of its stocks, tastes the wines of the different categories and promotes Port and Douro wines. In 2022 about 80 million litres were produced and 70 million sold, 82% of them abroad. The decline comes from inexpensive Ports drunk as aperitifs in France, the largest market, and the Netherlands, where other drinks are replacing them. The special categories (Reserve, LBV, Vintage, age-indicated Tawny and others) account for 23% of volume but 45% of value, and that is where producers are investing: aged Tawnies, increasingly in demand, and even 4.5-litre formats for hospitality. To attract new consumers, Rosé and White Port with tonic are promoted, including in cocktails, with lower alcohol than many spirits. Finally, some diversify into unfortified Douro wines, such as Symington, Quinta do Noval, Ramos Pinto and Niepoort, while Taylor's has focused on specialising in Port. Premiumisation protects margins but does not fully replace the lost volume.",
         "La propiedad de los viñedos está muy fragmentada: unos 20.000 propietarios con 2,2 hectáreas de media, que venden casi todos la uva a productores medianos y grandes o a cooperativas. Las cooperativas hacen alrededor del 20 % del vino pero, dada la fuerza de las marcas de las casas exportadoras, lo venden sobre todo a los productores; a menudo intervienen corredores. Aguas abajo el sector está muy concentrado: solo cuentan de verdad 30–35 productores y los cinco primeros, Gran Cruz, Symington Family Estates, Sogrape, The Fladgate Partnership y Sogevinus, hacen el 80 % del volumen. El IVDP regula la producción con el beneficio, limita las ventas anuales a un tercio de las existencias de cada productor, cata los vinos de las distintas categorías y promociona el Oporto y los vinos del Duero. En 2022 se produjeron unos 80 millones de litros y se vendieron 70, el 82 % en el extranjero. La caída procede de los Oportos económicos que se beben como aperitivo en Francia, primer mercado, y en los Países Bajos, donde otras bebidas los sustituyen. Las categorías especiales (Reserve, LBV, Vintage, Tawny con indicación de edad y otras) suponen el 23 % del volumen pero el 45 % del valor, y en ellas se concentra la apuesta: Tawny envejecidos, cada vez más demandados, e incluso formatos de 4,5 litros para la hostelería. Para atraer a nuevos consumidores se promueven el Rosé y el White Port con tónica, también en cócteles, con menos alcohol que muchos destilados. Por último, algunos diversifican hacia vinos tranquilos del Duero, como Symington, Quinta do Noval, Ramos Pinto y Niepoort, mientras Taylor's ha apostado por especializarse en el Oporto. La premiumización protege los márgenes, pero no sustituye del todo el volumen perdido."])]),
    /* ---------- Madeira, VDN, Rutherglen ---------- */
    Q("d5c", ["Un'etichetta di Madeira può indicare vitigno, dolcezza, età o annata.", "Une étiquette de Madère peut indiquer le cépage, la douceur, l'âge ou le millésime.", "A Madeira label may state grape variety, sweetness, age or vintage.", "Una etiqueta de Madeira puede indicar variedad, dulzor, edad o añada."], [
      P(["Spiega come si usano questi termini e che cosa dicono al consumatore su stile, qualità e prezzo.", "Expliquez comment ces mentions sont utilisées et ce qu'elles disent au consommateur sur le style, la qualité et le prix.", "Explain how these terms are used and what they tell the consumer about style, quality and price.", "Explica cómo se usan estos términos y qué dicen al consumidor sobre estilo, calidad y precio."], 12,
        ["dolcezza: extra dry, dry, medium dry, medium sweet o medium rich, sweet o rich, con sovrapposizioni tra produttori; Sercial extra dry o dry, il più chiaro e leggero, scorza di agrumi e frutta secca; Verdelho medium dry, più rotondo; Boal medium sweet, caramello e cioccolato; Malvasia o Malmsey sweet, pieno, bilanciato da acidità alta; Terrantez raro, delicato; Tinta Negra la più piantata, qualsiasi dolcezza, in etichetta dal 2015; data di imbottigliamento obbligatoria dal 2015; corrente: 2–3 anni, Tinta Negra ed estufagem, gran parte delle vendite; età 5, 10, 15, 20, 30, 40, 50 e oltre: indicazione di stile, approvata dall'IVBAM; 5 anni soprattutto Tinta Negra ed estufagem, buono o molto buono, prezzo medio; 10 anni e oltre: canteiro, spesso varietà bianche, 20 anni spesso eccezionale; Colheita: una sola annata, almeno 5 anni in legno, nata nel 2000; Frasqueira: annata, almeno 20 anni in legno, una sola varietà raccomandata, super-premium; Rainwater: medium dry, leggero, circa 18%, al massimo 10 anni",
         "douceur : extra dry, dry, medium dry, medium sweet ou medium rich, sweet ou rich, avec des recoupements entre producteurs ; Sercial extra dry ou dry, le plus clair et léger, zeste d'agrumes et fruits secs ; Verdelho medium dry, plus rond ; Boal medium sweet, caramel et chocolat ; Malvasia ou Malmsey sweet, ample, équilibré par une acidité élevée ; Terrantez rare, délicat ; Tinta Negra la plus plantée, toute douceur, sur l'étiquette depuis 2015 ; date de mise en bouteille obligatoire depuis 2015 ; corrente : 2–3 ans, Tinta Negra et estufagem, l'essentiel des ventes ; âges 5, 10, 15, 20, 30, 40, 50 et plus : indication de style, approuvée par l'IVBAM ; 5 ans surtout Tinta Negra et estufagem, bon à très bon, prix moyen ; 10 ans et plus : canteiro, souvent cépages blancs, 20 ans souvent exceptionnel ; Colheita : un seul millésime, au moins 5 ans sous bois, née en 2000 ; Frasqueira : millésime, au moins 20 ans sous bois, un seul cépage recommandé, super-premium ; Rainwater : medium dry, léger, environ 18 %, 10 ans au plus",
         "sweetness: extra dry, dry, medium dry, medium sweet or medium rich, sweet or rich, with overlap between producers; Sercial extra dry or dry, the palest and lightest, citrus peel and nuts; Verdelho medium dry, rounder; Boal medium sweet, caramel and chocolate; Malvasia or Malmsey sweet, full, balanced by high acidity; Terrantez rare, delicate; Tinta Negra the most planted, any sweetness, on labels since 2015; bottling date compulsory since 2015; corrente: 2–3 years, Tinta Negra and estufagem, most sales; ages 5, 10, 15, 20, 30, 40, 50 and over: an indication of style, approved by IVBAM; 5-year-old mostly Tinta Negra and estufagem, good to very good, mid-priced; 10 years and over: canteiro, often white varieties, 20-year-old often outstanding; Colheita: single vintage, at least 5 years in wood, created in 2000; Frasqueira: vintage, at least 20 years in wood, a single recommended variety, super-premium; Rainwater: medium dry, light, about 18%, at most 10 years",
         "dulzor: extra dry, dry, medium dry, medium sweet o medium rich, sweet o rich, con solapamientos entre productores; Sercial extra dry o dry, el más pálido y ligero, piel de cítricos y frutos secos; Verdelho medium dry, más redondo; Boal medium sweet, caramelo y chocolate; Malvasia o Malmsey sweet, lleno, equilibrado por una acidez alta; Terrantez escaso, delicado; Tinta Negra la más plantada, cualquier dulzor, en etiqueta desde 2015; fecha de embotellado obligatoria desde 2015; corrente: 2–3 años, Tinta Negra y estufagem, la mayor parte de las ventas; edades 5, 10, 15, 20, 30, 40, 50 y más: indicación de estilo, aprobada por el IVBAM; 5 años sobre todo Tinta Negra y estufagem, bueno o muy bueno, precio medio; 10 años o más: canteiro, a menudo variedades blancas, 20 años a menudo excepcional; Colheita: una sola añada, al menos 5 años en madera, creada en 2000; Frasqueira: añada, al menos 20 años en madera, una sola variedad recomendada, super-premium; Rainwater: medium dry, ligero, unos 18 %, como máximo 10 años"],
        ["Il Madeira si etichetta secondo dolcezza, vitigno, età e annata. I termini di dolcezza vanno da extra dry a sweet (o rich), ma si sovrappongono: il «dry» di un produttore può essere il «medium dry» di un altro. Sui vini varietali, quasi sempre i più cari, il nome del vitigno indica lo stile. Il Sercial è extra dry o dry, il più chiaro e leggero, con scorza di agrumi e frutta secca e acidità altissima; il Verdelho è medium dry, un po' più dolce e rotondo, con frutta candita; il Boal è medium sweet, più scuro e pieno, con caramello, cioccolato e frutta secca candita; la Malvasia (Malmsey) è sweet, piena e spesso bruna, ma bilanciata da un'acidità alta, con uva passa e caramello. Il Terrantez, rarissimo, è medium dry o medium sweet e sempre delicato. La Tinta Negra, il vitigno più piantato, si usa per tutte le dolcezze e dal 2015 può comparire in etichetta, ma di solito il vino porta solo il termine di dolcezza. Sempre dal 2015 è obbligatoria la data di imbottigliamento. La maggior parte del Madeira è «corrente»: vini da Tinta Negra con estufagem, vendibili dopo 2–3 anni, spesso con un nome di marca. Le indicazioni d'età (5, 10, 15, 20, 30, 40, 50 e «più di 50 anni») indicano uno stile, non un'età minima, e sono verificate dalla commissione dell'IVBAM. Il 5 anni è soprattutto Tinta Negra con estufagem, buono o molto buono e di prezzo medio; dai 10 anni il vino è passato tutto per il canteiro, spesso da varietà bianche, e dai 20 anni è spesso eccezionale, premium o super-premium. Tra i vini d'annata, il Colheita (dal 2000) richiede almeno 5 anni in legno; il Frasqueira almeno 20, da una sola varietà raccomandata, ed è super-premium. Il Rainwater, infine, è uno stile leggero e medium dry, intorno al 18%, al massimo con 10 anni.",
         "Le Madère s'étiquette selon la douceur, le cépage, l'âge et le millésime. Les mentions de douceur vont d'extra dry à sweet (ou rich), mais elles se chevauchent : le « dry » d'un producteur peut être le « medium dry » d'un autre. Sur les vins de cépage, presque toujours les plus chers, le nom du cépage indique le style. Le Sercial est extra dry ou dry, le plus clair et léger, au zeste d'agrumes et aux fruits secs, avec une acidité très élevée ; le Verdelho est medium dry, un peu plus doux et rond, aux fruits confits ; le Boal est medium sweet, plus foncé et ample, au caramel, au chocolat et aux fruits secs confits ; la Malvasia (Malmsey) est sweet, ample et souvent brune, mais équilibrée par une acidité élevée, aux raisins secs et au caramel. Le Terrantez, très rare, est medium dry ou medium sweet et toujours délicat. La Tinta Negra, le cépage le plus planté, sert à toutes les douceurs et peut figurer sur l'étiquette depuis 2015, mais le vin porte en général seulement la mention de douceur. Depuis 2015 aussi, la date de mise en bouteille est obligatoire. La majorité du Madère est « corrente » : des vins de Tinta Negra passés en estufagem, vendables après 2–3 ans, souvent sous un nom de marque. Les mentions d'âge (5, 10, 15, 20, 30, 40, 50 et « plus de 50 ans ») indiquent un style, pas un âge minimum, et sont vérifiées par le jury de l'IVBAM. Le 5 ans est surtout de la Tinta Negra passée en estufagem, bon à très bon et de prix moyen ; à partir de 10 ans le vin est passé entièrement par le canteiro, souvent issu de cépages blancs, et à partir de 20 ans il est souvent exceptionnel, premium ou super-premium. Parmi les millésimés, le Colheita (depuis 2000) exige au moins 5 ans sous bois ; le Frasqueira au moins 20, d'un seul cépage recommandé, et il est super-premium. Le Rainwater, enfin, est un style léger et medium dry, autour de 18 %, avec au plus 10 ans.",
         "Madeira is labelled by sweetness, grape variety, age and vintage. Sweetness terms run from extra dry to sweet (or rich), but they overlap: one producer's 'dry' can be another's 'medium dry'. On varietal wines, nearly always the dearer ones, the grape name signals the style. Sercial is extra dry or dry, the palest and lightest, with citrus peel and nuts and very high acidity; Verdelho is medium dry, a little sweeter and rounder, with candied fruit; Boal is medium sweet, darker and fuller, with caramel, chocolate and candied nuts; Malvasia (Malmsey) is sweet, full and often brown, yet balanced by high acidity, with raisin and caramel. Terrantez, very rare, is medium dry or medium sweet and always delicate. Tinta Negra, the most planted variety, is used at every sweetness level and may appear on the label since 2015, though the wine usually carries only a sweetness term. Since 2015 the bottling date has also been compulsory. Most Madeira is 'corrente': Tinta Negra wines made by estufagem, saleable after 2–3 years, often under a brand name. Age indications (5, 10, 15, 20, 30, 40, 50 and 'over 50 years') indicate a style, not a minimum age, and are verified by the IVBAM panel. Five-year-old wines are mostly Tinta Negra made by estufagem, good to very good and mid-priced; from 10 years the wine has all been through canteiro, often from white varieties, and from 20 years it is often outstanding, premium or super-premium. Among vintage wines, Colheita (since 2000) needs at least 5 years in wood; Frasqueira at least 20, from a single recommended variety, and is super-premium. Rainwater, finally, is a light, medium-dry style of about 18%, with at most a 10-year age indication.",
         "El Madeira se etiqueta según dulzor, variedad, edad y añada. Los términos de dulzor van de extra dry a sweet (o rich), pero se solapan: el «dry» de un productor puede ser el «medium dry» de otro. En los vinos varietales, casi siempre los más caros, el nombre de la variedad indica el estilo. El Sercial es extra dry o dry, el más pálido y ligero, con piel de cítricos y frutos secos y una acidez altísima; el Verdelho es medium dry, algo más dulce y redondo, con fruta confitada; el Boal es medium sweet, más oscuro y lleno, con caramelo, chocolate y frutos secos confitados; la Malvasia (Malmsey) es sweet, llena y a menudo marrón, pero equilibrada por una acidez alta, con pasas y caramelo. El Terrantez, escasísimo, es medium dry o medium sweet y siempre delicado. La Tinta Negra, la variedad más plantada, se usa en todos los dulzores y desde 2015 puede figurar en la etiqueta, aunque normalmente el vino solo lleva el término de dulzor. También desde 2015 es obligatoria la fecha de embotellado. La mayor parte del Madeira es «corrente»: vinos de Tinta Negra con estufagem, vendibles tras 2–3 años, a menudo con un nombre de marca. Las indicaciones de edad (5, 10, 15, 20, 30, 40, 50 y «más de 50 años») indican un estilo, no una edad mínima, y las verifica el panel del IVBAM. El de 5 años es sobre todo Tinta Negra con estufagem, bueno o muy bueno y de precio medio; desde los 10 años el vino ha pasado todo por el canteiro, a menudo de variedades blancas, y desde los 20 años suele ser excepcional, premium o super-premium. Entre los vinos de añada, el Colheita (desde 2000) exige al menos 5 años en madera; el Frasqueira al menos 20, de una sola variedad recomendada, y es super-premium. El Rainwater, por último, es un estilo ligero y medium dry, de unos 18 %, con un máximo de 10 años."])]),
    Q("d5c", ["Banyuls, Maury e Rivesaltes producono Vins Doux Naturels rossi in stile giovane e ossidativo.", "Banyuls, Maury et Rivesaltes produisent des Vins Doux Naturels rouges en style jeune et oxydatif.", "Banyuls, Maury and Rivesaltes make red Vins Doux Naturels in youthful and oxidative styles.", "Banyuls, Maury y Rivesaltes elaboran Vins Doux Naturels tintos en estilo joven y oxidativo."], [
      P(["Spiega come vigneto, vinificazione e maturazione creano questi stili e come sono indicati in etichetta.", "Expliquez comment le vignoble, la vinification et l'élevage créent ces styles et comment ils sont indiqués sur l'étiquette.", "Explain how the vineyard, winemaking and maturation create these styles and how they are shown on the label.", "Explica cómo el viñedo, la vinificación y la crianza crean estos estilos y cómo se indican en la etiqueta."], 12,
        ["Grenache Noir: tardivo, resistente alla siccità, accumula molto zucchero; Roussillon caldo e secco, Tramontana: concentrazione; rese basse, in genere 30 hL/ha, almeno 14,8% potenziale; fermentazione sulle bucce a circa 28 °C con rimontaggi e follature; fortificazione sulle bucce con spirito neutro al 95–96% a 5–8%: lo spirito aiuta l'estrazione; macerazione anche per settimane dopo la fortificazione; zucchero almeno 45 g/L, spesso circa 100; stile giovane: acciaio sigillato, freddo, gas inerte, venduto dopo pochi mesi, mora, lampone, prugna; Grenat a Maury e Rivesaltes, Rimage a Banyuls; stile ossidativo: botti vecchie non colmate o damigiane di vetro al sole; Tuilé a Maury e Rivesaltes, Traditionnel a Banyuls, Hors d'âge più lungo, Rancio; Banyuls almeno 50% Grenache Noir su terrazze di scisto; Banyuls Grand Cru almeno 75% e 30 mesi; Maury almeno 75%, scisto scuro 100–400 m; quasi tutto consumato in Francia, 2% esportato",
         "Grenache Noir : tardif, résistant à la sécheresse, accumule beaucoup de sucre ; Roussillon chaud et sec, Tramontane : concentration ; rendements bas, en général 30 hL/ha, au moins 14,8 % potentiel ; fermentation sur les peaux vers 28 °C avec remontages et pigeages ; mutage sur les peaux avec un alcool neutre à 95–96 % à 5–8 % : l'alcool aide l'extraction ; macération possible plusieurs semaines après le mutage ; sucre au moins 45 g/L, souvent environ 100 ; style jeune : inox fermé, frais, gaz inerte, vendu après quelques mois, mûre, framboise, prune ; Grenat à Maury et Rivesaltes, Rimage à Banyuls ; style oxydatif : vieux fûts non ouillés ou bonbonnes de verre au soleil ; Tuilé à Maury et Rivesaltes, Traditionnel à Banyuls, Hors d'âge plus long, Rancio ; Banyuls au moins 50 % de Grenache Noir sur terrasses de schiste ; Banyuls Grand Cru au moins 75 % et 30 mois ; Maury au moins 75 %, schiste sombre 100–400 m ; presque tout consommé en France, 2 % exporté",
         "Grenache Noir: late ripening, drought-resistant, accumulates plenty of sugar; hot, dry Roussillon, Tramontane: concentration; low yields, generally 30 hL/ha, at least 14.8% potential; fermentation on the skins at about 28 °C with pumping over and punching down; fortification on the skins with 95–96% neutral spirit at 5–8%: the spirit aids extraction; maceration can continue for weeks after fortification; sugar at least 45 g/L, often about 100; youthful style: sealed steel, cool, inert gas, released after a few months, blackberry, raspberry, plum; Grenat in Maury and Rivesaltes, Rimage in Banyuls; oxidative style: old casks not topped up or glass demijohns in the sun; Tuilé in Maury and Rivesaltes, Traditionnel in Banyuls, Hors d'âge longer, Rancio; Banyuls at least 50% Grenache Noir on schist terraces; Banyuls Grand Cru at least 75% and 30 months; Maury at least 75%, dark schist at 100–400 m; nearly all drunk in France, 2% exported",
         "Garnacha Tinta: tardía, resistente a la sequía, acumula mucho azúcar; Rosellón cálido y seco, Tramontana: concentración; rendimientos bajos, en general 30 hL/ha, al menos 14,8 % potencial; fermentación con los hollejos a unos 28 °C con remontados y bazuqueos; encabezado con los hollejos con alcohol neutro al 95–96 % a 5–8 %: el alcohol ayuda a extraer; maceración posible durante semanas tras el encabezado; azúcar al menos 45 g/L, a menudo unos 100; estilo joven: acero cerrado, frío, gas inerte, a la venta a los pocos meses, mora, frambuesa, ciruela; Grenat en Maury y Rivesaltes, Rimage en Banyuls; estilo oxidativo: barricas viejas sin rellenar o damajuanas de vidrio al sol; Tuilé en Maury y Rivesaltes, Traditionnel en Banyuls, Hors d'âge más largo, Rancio; Banyuls al menos 50 % de Garnacha Tinta en terrazas de esquisto; Banyuls Grand Cru al menos 75 % y 30 meses; Maury al menos 75 %, esquisto oscuro a 100–400 m; casi todo se bebe en Francia, 2 % exportado"],
        ["Il Grenache Noir è tardivo, resiste alla siccità e accumula molto zucchero: è adatto al Roussillon, la zona più calda e secca dei VDN, dove la Tramontana, fresca e asciutta, aumenta la traspirazione degli acini a fine maturazione e concentra lo zucchero. Le rese sono basse, in genere intorno ai 30 hL/ha, e la legge impone almeno 14,8% di alcol potenziale. In cantina il rosso fermenta sulle bucce a circa 28 °C, con rimontaggi e follature; quando il mosto ha 5–8% di alcol si aggiunge spirito neutro al 95–96%, mentre il liquido è ancora sulle bucce: lo spirito aiuta a estrarre colore, aromi e tannino, e la macerazione può proseguire per un paio di settimane. Lo zucchero residuo deve essere almeno 45 g/L, ma molti vini sono intorno ai 100. Poi lo stile dipende dalla maturazione. I vini giovani restano in vasche d'acciaio sigillate, al fresco e sotto gas inerte, e si vendono dopo pochi mesi: colore intenso, mora, lampone e prugna. In etichetta sono Grenat a Maury e Rivesaltes e Rimage a Banyuls. I vini ossidativi maturano anni in botti vecchie non colmate, oppure in damigiane di vetro lasciate al sole per accelerare l'evoluzione: diventano tawny, con frutta secca e noce. Si chiamano Tuilé a Maury e Rivesaltes, Traditionnel a Banyuls; Hors d'âge indica una maturazione più lunga e Rancio un carattere rancio. Le regole delle denominazioni rafforzano la qualità: Banyuls, su terrazze ripide di scisto, richiede almeno il 50% di Grenache Noir, Banyuls Grand Cru almeno il 75% e 30 mesi di maturazione; Maury, su scisti scuri tra 100 e 400 m che rilasciano calore di notte, almeno il 75%. Il mercato è quasi solo francese: appena il 2% viene esportato.",
         "Le Grenache Noir est tardif, résiste à la sécheresse et accumule beaucoup de sucre : il convient au Roussillon, la zone la plus chaude et sèche des VDN, où la Tramontane, fraîche et sèche, accroît la transpiration des baies en fin de maturation et concentre le sucre. Les rendements sont bas, en général autour de 30 hL/ha, et la loi impose au moins 14,8 % d'alcool potentiel. Au chai, le rouge fermente sur les peaux vers 28 °C, avec remontages et pigeages ; quand le moût atteint 5 à 8 % d'alcool, on ajoute un alcool neutre à 95–96 % alors que le liquide est encore sur les peaux : l'alcool aide à extraire couleur, arômes et tanin, et la macération peut se poursuivre une quinzaine de jours. Le sucre résiduel doit être d'au moins 45 g/L, mais beaucoup de vins tournent autour de 100. Le style dépend ensuite de l'élevage. Les vins jeunes restent en cuves inox fermées, au frais et sous gaz inerte, et sont vendus après quelques mois : couleur intense, mûre, framboise et prune. Sur l'étiquette, ce sont des Grenat à Maury et Rivesaltes et des Rimage à Banyuls. Les vins oxydatifs s'élèvent des années en vieux fûts non ouillés, ou en bonbonnes de verre laissées au soleil pour accélérer l'évolution : ils deviennent tuilés, aux fruits secs et à la noix. On les appelle Tuilé à Maury et Rivesaltes, Traditionnel à Banyuls ; Hors d'âge signale un élevage plus long et Rancio un caractère rancio. Les règles des appellations renforcent la qualité : Banyuls, sur des terrasses de schiste escarpées, exige au moins 50 % de Grenache Noir, Banyuls Grand Cru au moins 75 % et 30 mois d'élevage ; Maury, sur des schistes sombres entre 100 et 400 m qui restituent la chaleur la nuit, au moins 75 %. Le marché est presque uniquement français : 2 % seulement sont exportés.",
         "Grenache Noir ripens late, resists drought and accumulates plenty of sugar: it suits Roussillon, the hottest and driest VDN area, where the cool, dry Tramontane increases berry transpiration at the end of ripening and concentrates sugar. Yields are low, generally around 30 hL/ha, and the law requires at least 14.8% potential alcohol. In the winery the red ferments on its skins at about 28 °C, with pumping over and punching down; when the must reaches 5–8% abv, 95–96% neutral spirit is added while the liquid is still on the skins: the spirit helps extract colour, flavour and tannin, and maceration may continue for a couple of weeks. Residual sugar must be at least 45 g/L, though many wines are around 100. Style then depends on maturation. Youthful wines stay in sealed stainless steel tanks, cool and under inert gas, and are sold after a few months: deep colour, blackberry, raspberry and plum. On the label they are Grenat in Maury and Rivesaltes and Rimage in Banyuls. Oxidative wines age for years in old casks that are not topped up, or in glass demijohns left in the sun to speed up development: they turn tawny, with dried fruit and walnut. They are called Tuilé in Maury and Rivesaltes and Traditionnel in Banyuls; Hors d'âge signals longer ageing and Rancio a rancio character. Appellation rules reinforce quality: Banyuls, on steep schist terraces, requires at least 50% Grenache Noir, Banyuls Grand Cru at least 75% and 30 months' ageing; Maury, on dark schists at 100–400 m that release heat at night, at least 75%. The market is almost entirely French: only 2% is exported.",
         "La Garnacha Tinta es tardía, resiste la sequía y acumula mucho azúcar: encaja en el Rosellón, la zona más cálida y seca de los VDN, donde la Tramontana, fresca y seca, aumenta la transpiración de las bayas al final de la maduración y concentra el azúcar. Los rendimientos son bajos, en general en torno a 30 hL/ha, y la ley exige al menos 14,8 % de alcohol potencial. En bodega el tinto fermenta con los hollejos a unos 28 °C, con remontados y bazuqueos; cuando el mosto tiene 5–8 % de alcohol se añade alcohol neutro al 95–96 % con el líquido todavía en contacto con los hollejos: el alcohol ayuda a extraer color, aromas y tanino, y la maceración puede seguir un par de semanas. El azúcar residual debe ser de al menos 45 g/L, aunque muchos vinos rondan los 100. Después el estilo depende de la crianza. Los vinos jóvenes permanecen en depósitos de acero cerrados, en frío y bajo gas inerte, y se venden a los pocos meses: color intenso, mora, frambuesa y ciruela. En la etiqueta son Grenat en Maury y Rivesaltes y Rimage en Banyuls. Los vinos oxidativos se crían años en barricas viejas sin rellenar, o en damajuanas de vidrio al sol para acelerar la evolución: se vuelven tawny, con frutos secos y nuez. Se llaman Tuilé en Maury y Rivesaltes y Traditionnel en Banyuls; Hors d'âge indica una crianza más larga y Rancio un carácter rancio. Las normas de las denominaciones refuerzan la calidad: Banyuls, en terrazas empinadas de esquisto, exige al menos un 50 % de Garnacha Tinta, Banyuls Grand Cru al menos un 75 % y 30 meses de crianza; Maury, sobre esquistos oscuros entre 100 y 400 m que devuelven el calor por la noche, al menos un 75 %. El mercado es casi solo francés: apenas se exporta el 2 %."])]),
    Q("d5c", ["I Rutherglen Muscat sono classificati in quattro livelli.", "Les Rutherglen Muscat sont classés en quatre niveaux.", "Rutherglen Muscats are classified in four levels.", "Los Rutherglen Muscat se clasifican en cuatro niveles."], [
      P(["Spiega come funziona la classificazione e come i produttori usano vigneto, maturazione e assemblaggio per costruire ogni livello e il loro stile di casa.", "Expliquez comment fonctionne la classification et comment les producteurs utilisent le vignoble, l'élevage et l'assemblage pour construire chaque niveau et leur style maison.", "Explain how the classification works and how producers use the vineyard, maturation and blending to build each level and their house style.", "Explica cómo funciona la clasificación y cómo los productores usan el viñedo, la crianza y la mezcla para construir cada nivel y su estilo de casa."], 10,
        ["Muscat of Rutherglen Network fondato nel 1995 per promuovere le vendite; quattro livelli per ricchezza, complessità e intensità, giudicati all'assaggio e non sull'età; Rutherglen Muscat: età media 3–5 anni, 180–240 g/L; Classic: 6–10 anni, 200–280 g/L; Grand: 11–19 anni, 270–400 g/L; Rare: almeno 20 anni, 270–400 g/L, volumi minimi; più si sale, più annate e più anni tra la più giovane e la più vecchia; parcelle raccolte in momenti diversi: uve fresche e aromatiche o appassite e ricche; viti vecchie, 20–90 anni, più intensità; botti in alto più calde, maturazione rapida; zone isolate più fresche; botti piccole da 180–500 L: più evaporazione e ossidazione, grandi da 1.300–9.000 L più lente; colmature frequenti per uno stile fresco, rare per uno ossidativo; solera modificata; stili di casa: Pfeiffer più leggero, All Saints e Morris più intensi",
         "Muscat of Rutherglen Network fondé en 1995 pour promouvoir les ventes ; quatre niveaux selon la richesse, la complexité et l'intensité, jugés à la dégustation et non sur l'âge ; Rutherglen Muscat : âge moyen 3–5 ans, 180–240 g/L ; Classic : 6–10 ans, 200–280 g/L ; Grand : 11–19 ans, 270–400 g/L ; Rare : au moins 20 ans, 270–400 g/L, volumes infimes ; plus on monte, plus il y a de millésimes et d'années entre le plus jeune et le plus vieux ; parcelles vendangées à des moments différents : raisins frais et aromatiques ou passerillés et riches ; vieilles vignes, 20–90 ans, plus d'intensité ; fûts du haut plus chauds, élevage rapide ; zones isolées plus fraîches ; petits fûts de 180–500 L : plus d'évaporation et d'oxydation, grands de 1 300–9 000 L plus lents ; ouillages fréquents pour un style frais, rares pour un style oxydatif ; solera modifiée ; styles maison : Pfeiffer plus léger, All Saints et Morris plus intenses",
         "Muscat of Rutherglen Network founded in 1995 to promote sales; four levels by richness, complexity and intensity, judged on taste not age; Rutherglen Muscat: average age 3–5 years, 180–240 g/L; Classic: 6–10 years, 200–280 g/L; Grand: 11–19 years, 270–400 g/L; Rare: at least 20 years, 270–400 g/L, tiny volumes; the higher the level, the more vintages and the wider the span of years; blocks picked at different times: fresh, aromatic grapes or shrivelled, rich ones; old vines, 20–90 years, more intensity; casks at the top warmer, faster maturation; insulated areas cooler; small casks of 180–500 L: more evaporation and oxidation, large ones of 1,300–9,000 L slower; frequent topping up for a fresh style, rare for an oxidative one; modified solera; house styles: Pfeiffer lighter, All Saints and Morris more intense",
         "Muscat of Rutherglen Network fundada en 1995 para promover las ventas; cuatro niveles según riqueza, complejidad e intensidad, juzgados en cata y no por la edad; Rutherglen Muscat: edad media 3–5 años, 180–240 g/L; Classic: 6–10 años, 200–280 g/L; Grand: 11–19 años, 270–400 g/L; Rare: al menos 20 años, 270–400 g/L, volúmenes mínimos; cuanto más alto, más añadas y más años entre la más joven y la más vieja; parcelas vendimiadas en momentos distintos: uva fresca y aromática o pasificada y rica; viñas viejas, 20–90 años, más intensidad; barricas de arriba más calientes, crianza rápida; zonas aisladas más frescas; barricas pequeñas de 180–500 L: más evaporación y oxidación, grandes de 1.300–9.000 L más lentas; rellenos frecuentes para un estilo fresco, escasos para uno oxidativo; solera modificada; estilos de casa: Pfeiffer más ligero, All Saints y Morris más intensos"],
        ["La classificazione è stata introdotta dalla Muscat of Rutherglen Network, fondata nel 1995 per promuovere le vendite e alla quale appartiene la maggior parte dei pochi produttori. Ha quattro livelli definiti da ricchezza, complessità e intensità, giudicate all'assaggio e non dall'età, anche se la durata della maturazione è il fattore decisivo. Il Rutherglen Muscat di base ha un'età media di 3–5 anni e 180–240 g/L di zucchero; il Classic 6–10 anni e 200–280 g/L; il Grand 11–19 anni e 270–400 g/L; il Rare almeno 20 anni, con componenti molto più vecchi, 270–400 g/L e volumi minimi. Salendo di livello aumentano il numero di annate nell'assemblaggio e la distanza tra la più giovane e la più vecchia. I primi due livelli si producono in volumi molto più grandi, e molti produttori fanno tutte e quattro le categorie. Ogni livello si costruisce con scelte precise. In vigneto si raccolgono parcelle in momenti diversi, uve meno mature per gli aromi freschi del Moscato e uve appassite per zucchero e frutta secca, e si usano viti vecchie, spesso tra 20 e 90 anni, per intensità e ricchezza. In cantina conta la posizione della botte: in alto, sotto i tetti di lamiera, fa più caldo e il vino matura più in fretta; zone isolate danno una maturazione lenta e più fresca. Le botti piccole (180–500 L) evaporano e ossidano di più e concentrano più in fretta; quelle grandi (1.300–9.000 L) rallentano. Colmare spesso conserva freschezza, colmare di rado sviluppa note ossidative. Infine l'assemblaggio di vini giovani e vecchi, talvolta con una solera modificata, bilancia freschezza e complessità e mantiene lo stile di casa: Pfeiffer è noto per uno stile più leggero e fresco, All Saints e Morris per vini più intensi e opulenti.",
         "La classification a été introduite par la Muscat of Rutherglen Network, fondée en 1995 pour promouvoir les ventes et à laquelle appartiennent la plupart des rares producteurs. Elle compte quatre niveaux définis par la richesse, la complexité et l'intensité, jugées à la dégustation et non sur l'âge, même si la durée d'élevage est le facteur décisif. Le Rutherglen Muscat de base a un âge moyen de 3 à 5 ans et 180–240 g/L de sucre ; le Classic 6 à 10 ans et 200–280 g/L ; le Grand 11 à 19 ans et 270–400 g/L ; le Rare au moins 20 ans, avec des composants bien plus vieux, 270–400 g/L et des volumes infimes. Plus on monte, plus augmentent le nombre de millésimes de l'assemblage et l'écart entre le plus jeune et le plus vieux. Les deux premiers niveaux sont produits en volumes bien plus importants, et beaucoup de producteurs font les quatre catégories. Chaque niveau se construit par des choix précis. À la vigne, on vendange des parcelles à des moments différents, des raisins moins mûrs pour les arômes frais du Muscat et des raisins passerillés pour le sucre et les fruits secs, et l'on utilise de vieilles vignes, souvent de 20 à 90 ans, pour l'intensité et la richesse. Au chai, la position du fût compte : en haut, sous les toits de tôle, il fait plus chaud et le vin mûrit plus vite ; des zones isolées donnent un élevage lent et plus frais. Les petits fûts (180–500 L) évaporent et oxydent davantage et concentrent plus vite ; les grands (1 300–9 000 L) ralentissent. Ouiller souvent garde la fraîcheur, ouiller rarement développe des notes oxydatives. Enfin, l'assemblage de vins jeunes et vieux, parfois en solera modifiée, équilibre fraîcheur et complexité et maintient le style maison : Pfeiffer est connu pour un style plus léger et frais, All Saints et Morris pour des vins plus intenses et opulents.",
         "The classification was introduced by the Muscat of Rutherglen Network, founded in 1995 to promote sales, to which most of the few producers belong. It has four levels defined by richness, complexity and intensity, judged on taste rather than age, although length of maturation is the decisive factor. Basic Rutherglen Muscat has an average age of 3–5 years and 180–240 g/L of sugar; Classic 6–10 years and 200–280 g/L; Grand 11–19 years and 270–400 g/L; Rare at least 20 years, with much older components, 270–400 g/L and tiny volumes. Moving up, the number of vintages in the blend and the span between the youngest and oldest increase. The first two levels are made in much larger volumes, and many producers make all four. Each level is built through specific choices. In the vineyard, blocks are picked at different times, less ripe grapes for fresh Muscat aromas and shrivelled grapes for sugar and dried fruit, and old vines, often 20–90 years old, are used for intensity and richness. In the winery cask position matters: at the top, under tin roofs, it is hotter and the wine matures faster; insulated areas give slower, fresher maturation. Small casks (180–500 L) evaporate and oxidise more and concentrate faster; large ones (1,300–9,000 L) slow things down. Frequent topping up keeps freshness, infrequent topping up develops oxidative notes. Finally, blending young and old wines, sometimes in a modified solera, balances freshness and complexity and maintains the house style: Pfeiffer is known for a lighter, fresher style, All Saints and Morris for more intense, luscious wines.",
         "La clasificación la introdujo la Muscat of Rutherglen Network, fundada en 1995 para promover las ventas y a la que pertenece la mayoría de los pocos productores. Tiene cuatro niveles definidos por riqueza, complejidad e intensidad, juzgadas en cata y no por la edad, aunque la duración de la crianza es el factor decisivo. El Rutherglen Muscat básico tiene una edad media de 3–5 años y 180–240 g/L de azúcar; el Classic 6–10 años y 200–280 g/L; el Grand 11–19 años y 270–400 g/L; el Rare al menos 20 años, con componentes mucho más viejos, 270–400 g/L y volúmenes mínimos. Al subir de nivel aumentan el número de añadas en la mezcla y la distancia entre la más joven y la más vieja. Los dos primeros niveles se producen en volúmenes mucho mayores, y muchos productores elaboran las cuatro categorías. Cada nivel se construye con decisiones concretas. En el viñedo se vendimian parcelas en momentos distintos, uva menos madura para los aromas frescos del Moscatel y uva pasificada para azúcar y frutos secos, y se usan viñas viejas, a menudo de 20 a 90 años, por su intensidad y riqueza. En bodega importa la posición de la barrica: arriba, bajo los techos de chapa, hace más calor y el vino madura más deprisa; las zonas aisladas dan una crianza lenta y más fresca. Las barricas pequeñas (180–500 L) evaporan y oxidan más y concentran más rápido; las grandes (1.300–9.000 L) frenan el proceso. Rellenar a menudo conserva frescura, rellenar poco desarrolla notas oxidativas. Por último, la mezcla de vinos jóvenes y viejos, a veces en una solera modificada, equilibra frescura y complejidad y mantiene el estilo de la casa: Pfeiffer es conocido por un estilo más ligero y fresco, All Saints y Morris por vinos más intensos y opulentos."])])
  ]
};
